85	import { createHash } from "node:crypto";
86	import { cookies } from "next/headers";
87	import { ContourError } from "@contour/sdk/core";
88	import type { HostUser, Membership } from "@contour/sdk/server";
89	import { getSession } from "@/lib/session";
90	import { getDb } from "@/lib/db";
91	
92	const APP_ID = "northwind";
93	const TENANT_ID = "northwind"; // company, not the current support team
94	const allowedRoles = new Set(["agent", "lead", "admin"]); // owner-approved
95	async function getMembership(subjectId: string, tenantId: string, appId: string): Promise<Membership | null> {
96	  if (tenantId !== TENANT_ID || appId !== APP_ID) return null;
97	  const { data, error } = await getDb().from("users")
98	    .select("id,name,role,role_version").eq("id", subjectId).maybeSingle();
99	  if (error) throw new Error("Membership lookup failed");
100	  if (!data) return null;
101	  return {
102	    subjectId: data.id, tenantId, appId, role: data.role,
103	    roleVersion: data.role_version, displayName: data.name,
104	    status: "active", dataAccess: allowedRoles.has(data.role),
105	  };
106	}
107	async function currentUser(): Promise<HostUser | null> {
108	  const session = await getSession();
109	  if (!session) return null;
110	  const membership = await getMembership(session.userId, TENANT_ID, APP_ID);
111	  const cookie = (await cookies()).get("nw_session")?.value;
112	  if (!membership || membership.status !== "active") throw new ContourError("FORBIDDEN", "No active membership");
113	  if (!cookie) throw new ContourError("FORBIDDEN", "Verified session cookie missing");
114	  return {
