4	import type { CsatPoint, Session } from "./types";
5	/** Return a response-weighted daily satisfaction percentage for authorized teams. */
6	export async function getCsatTrend(session: Session, options: { range: "7d" | "30d" }): Promise<CsatPoint[]> {
7	  const range = z.enum(["7d", "30d"]).parse(options.range);
8	  const cutoff = new Date();
9	  cutoff.setUTCDate(cutoff.getUTCDate() - (range === "7d" ? 6 : 29));
10	  const { data, error } = await scopedQuery(session, "csat_scores", "date,score,responses,team").gte("date", cutoff.toISOString().slice(0, 10)).order("date", { ascending: true }).limit(1000).returns<(CsatPoint & { team: string })[]>();
11	  checkDbError(error);
12	  const days = new Map<string, { total: number; count: number }>();
13	  for (const row of data ?? []) {
14	    const day = days.get(row.date) ?? { total: 0, count: 0 };
15	    day.total += row.score * row.responses; day.count += row.responses;
16	    days.set(row.date, day);
17	  }
18	  return [...days].sort(([a], [b]) => a.localeCompare(b)).map(([date, day]) => ({ date, score: Math.round(day.total / day.count * 10) / 10, responses: day.count }));
19	}
