1	import "server-only";
2	import type { SupabaseClient } from "@supabase/supabase-js";
3	import type { ContourStore, Membership } from "../core/broker";
4	import type { VerifiedContext } from "../core/types";
5	import { createServerContext } from "./context";
6	import { createCsrf } from "./host/csrf";
7	import { createHostRoute } from "./host/host-route";
8	import { createMcpHandler } from "./mcp/handler";
9	import type { McpToolSet } from "./mcp/tools";
10	import { createAuthorize, type AuthorizeValidation, type RawParams } from "./oauth/authorize";
11	import { createClients } from "./oauth/clients";
12	import { createCodes } from "./oauth/codes";
13	import { authorizationServerMetadata, NO_STORE_HEADERS, protectedResourceMetadata } from "./oauth/config";
14	import { createConsent } from "./oauth/consent";
15	import { OAuthError, oauthErrorResponse } from "./oauth/errors";
16	import { createGrants, type GrantSummary } from "./oauth/grants";
17	import { PUBLIC_CORS_HEADERS, publicClientId, readBodyCapped, readFormBody } from "./oauth/http";
18	import { clientIp, createRateLimiter } from "./oauth/ratelimit";
19	import { createResolver } from "./oauth/resolve";
20	import { createTokens } from "./oauth/tokens";
21	import { supabaseStore } from "./store/supabase-store";
22	
23	export type { Membership };
24	
25	/** A verified company session, resolved by the host's own auth. */
26	export type HostUser = {
27	  subjectId: string;
28	  /** Auth session ID; binds CSRF tokens to this sign-in. */
29	  sessionId: string;
30	  tenantId: string;
31	  role: string;
32	  roleVersion: number;
33	  displayName: string;
34	  email: string;
35	};
36	
37	export type ContourServerConfig = {
38	  /** Public origin of the deployment, no trailing slash. OAuth issuer; the MCP resource is `${appUrl}/api/mcp`. */
39	  appUrl: string;
40	  appId: string;
41	  /** Shown in protected resource metadata and on consent. */
42	  resourceName: string;
43	  /** Grantable surfaces. The first one is the default (host sessions, MCP connection check). */
44	  surfaces: readonly string[];
45	  /** Service-role client. Never exposed to browsers, agents or prompts. */
46	  db: SupabaseClient;
47	  /** Postgres schema with the Contour and OAuth tables: "public" for ops-demo. */
48	  schema: string;
49	  csrfSecret: string;
50	  identity: {
51	    /**
52	     * The verified company session, or null when signed out. May throw
53	     * ContourError("FORBIDDEN") when the user is signed in but has no active
54	     * membership for this app.
55	     */
56	    currentUser(): Promise<HostUser | null>;
57	    /** Relative path in the host app that signs the user in, then returns to `nextPath`. */
58	    loginUrl(nextPath: string): string;
59	    /**
60	     * Membership for a subject in a tenant and app. The store delegates to this,
61	     * so it must read the host's own records and must not call `store.getMembership`.
62	     */
63	    getMembership(subjectId: string, tenantId: string, appId: string): Promise<Membership | null>;
64	  };
65	  /** Company-wide and tenant agent switch for MCP access (both must be on). */
66	  agentAccessEnabled(tenantId: string, appId: string): Promise<boolean>;
67	  /** Client ID Metadata Document URLs shown as verified on consent (e.g. Contour Cloud). */
68	  trustedClients?: readonly string[];
69	  consent?: { productName: string; dataCategories: string[]; brandColor?: string };
70	};
71	
72	export type ContourServer = {
73	  config: ContourServerConfig;
74	  /** Verifies the MCP bearer token and builds the broker context for `surfaceId`. */
75	  resolveMcpContext(req: Request, surfaceId: string): Promise<VerifiedContext>;
76	  oauth: {
77	    protectedResourceMetadata(): object;
78	    authorizationServerMetadata(): object;
79	    validateAuthorize(raw: Record<string, string | string[] | undefined>): Promise<AuthorizeValidation>;
80	    /** Builds the client redirect for a code or an error, including RFC 9207 `iss`. */
81	    buildClientRedirect(redirectUri: string, params: Record<string, string | null | undefined>): string;
82	    /** Consent form POST (Approve / Deny). */
83	    decision(req: Request): Promise<Response>;
84	    token(req: Request): Promise<Response>;
85	    register(req: Request): Promise<Response>;
86	    revoke(req: Request): Promise<Response>;
87	    csrfTokenFor(user: HostUser): string;
88	    listGrantsForUser(subjectId: string, tenantId: string): Promise<GrantSummary[]>;
89	    revokeGrant(subjectId: string, tenantId: string, grantId: string): Promise<boolean>;
90	    revokeAllGrantsForApp(tenantId: string, appId: string, by?: string): Promise<number>;
91	  };
92	  /** Builds the MCP POST handler for a tool set. */
93	  mcp(handlerOpts: { tools: McpToolSet; instructions: string }): (req: Request) => Promise<Response>;
94	  /** supabaseStore({ client: db, schema }) with this config's agent switch and identity membership. */
95	  store: ContourStore;
96	  /** Same-origin + session-bound CSRF header check for host mutations. Throws ContourError FORBIDDEN. */
97	  assertCsrf(req: Request, user: HostUser): void;
98	  /** The verified host session; throws ContourError UNAUTHENTICATED when signed out. */
99	  requireUser(): Promise<HostUser>;
100	  /** Broker context for a verified host session (all scopes, host channel). */
101	  contextFromUser(user: HostUser, surfaceId?: string): VerifiedContext;
102	  /** Authenticated host mutation: verified session + same origin + CSRF + JSON body (32 KB cap). */
103	  hostMutation(req: Request, fn: (ctx: VerifiedContext, body: unknown) => Promise<unknown>): Promise<Response>;
104	};
105	
106	const MAX_REGISTRATION_BODY = 8 * 1024;
107	
108	/**
109	 * Builds the OAuth 2.1 authorization server, MCP resource server, store and
110	 * host helpers for one app. Nothing is read from the config at construction
111	 * time, so config getters (env-backed values, a lazily created client) stay
112	 * lazy and live.
113	 */
114	export function defineContourServer(cfg: ContourServerConfig): ContourServer {
115	  const ctx = createServerContext(cfg);
116	  const csrf = createCsrf(ctx);
117	  const rateLimiter = createRateLimiter(ctx);
118	  const clients = createClients(ctx, rateLimiter);
119	  const codes = createCodes(ctx);
120	  const grants = createGrants(ctx);
121	  const authorize = createAuthorize(ctx, clients);
122	  const tokens = createTokens(ctx, { clients, codes, grants, authorize });
123	  const resolver = createResolver(ctx, { grants, tokens });
124	  const consent = createConsent(ctx, { csrf, authorize, grants, codes });
125	  const host = createHostRoute(ctx, csrf);
126	  const store = supabaseStore({
127	    client: () => cfg.db,
128	    schema: cfg.schema,
129	    agentAccessEnabled: (tenantId, appId) => cfg.agentAccessEnabled(tenantId, appId),
130	    // Resolved per call so a getter-backed identity config stays lazy. The
131	    // identity adapter must not call `store.getMembership` (it would recurse).
132	    getMembership: (subjectId, tenantId, appId) => cfg.identity.getMembership(subjectId, tenantId, appId),
133	  });
134	
135	  /** OAuth 2.1 token endpoint: authorization_code (+PKCE S256) and refresh_token (rotating). */
136	  async function token(request: Request): Promise<Response> {
137	    try {
138	      if (!(await rateLimiter.allowRequest("token", clientIp(request), 60, 60))) {
139	        throw new OAuthError("temporarily_unavailable", "Too many token requests; retry shortly", 429);
140	      }
141	      const params = await readFormBody(request);
142	      const grantTypes = params.getAll("grant_type");
143	      if (grantTypes.length !== 1) throw new OAuthError("invalid_request", "grant_type is required exactly once");
144	      const clientId = publicClientId(request, params);
145	      let body;
146	      if (grantTypes[0] === "authorization_code") body = await tokens.exchangeAuthorizationCode(params, clientId);
147	      else if (grantTypes[0] === "refresh_token") body = await tokens.refreshAccessToken(params, clientId);
148	      else throw new OAuthError("unsupported_grant_type", "Supported grant types: authorization_code, refresh_token");
149	      return Response.json(body, { headers: { ...NO_STORE_HEADERS, ...PUBLIC_CORS_HEADERS } });
150	    } catch (e) {
151	      return oauthErrorResponse(e, PUBLIC_CORS_HEADERS);
152	    }
153	  }
154	
155	  /** RFC 7591 Dynamic Client Registration (public clients only). */
156	  async function register(request: Request): Promise<Response> {
157	    try {
158	      if (!(await rateLimiter.allowRequest("dcr", clientIp(request), 3600, 60))) {
159	        throw new OAuthError("temporarily_unavailable", "Too many registrations from this address; retry later", 429);
160	      }
161	      const type = request.headers.get("content-type") ?? "";
162	      if (!type.toLowerCase().startsWith("application/json")) {
163	        throw new OAuthError("invalid_client_metadata", "Content-Type must be application/json");
164	      }
165	      let body: unknown;
166	      try {
167	        body = JSON.parse(await readBodyCapped(request, MAX_REGISTRATION_BODY));
168	      } catch (e) {
169	        if (e instanceof OAuthError) throw e;
170	        throw new OAuthError("invalid_client_metadata", "Body must be valid JSON");
171	      }
172	      const registered = await clients.registerDynamicClient(body);
173	      return Response.json(registered, { status: 201, headers: { ...NO_STORE_HEADERS, ...PUBLIC_CORS_HEADERS } });
174	    } catch (e) {
175	      return oauthErrorResponse(e, PUBLIC_CORS_HEADERS);
176	    }
177	  }
178	
179	  /** RFC 7009 token revocation. Always 200 for well-formed requests (§2.2). */
180	  async function revoke(request: Request): Promise<Response> {
181	    try {
182	      if (!(await rateLimiter.allowRequest("revoke", clientIp(request), 60, 60))) {
183	        throw new OAuthError("temporarily_unavailable", "Too many requests; retry shortly", 429);
184	      }
185	      const params = await readFormBody(request);
186	      const presented = params.getAll("token");
187	      if (presented.length !== 1 || !presented[0]) throw new OAuthError("invalid_request", "token is required exactly once");
188	      const clientIds = params.getAll("client_id");
189	      if (clientIds.length > 1) throw new OAuthError("invalid_request", "Duplicate client_id parameter");
190	      await tokens.revokePresentedToken(presented[0], clientIds[0] || undefined);
191	      return new Response(null, { status: 200, headers: { ...NO_STORE_HEADERS, ...PUBLIC_CORS_HEADERS } });
192	    } catch (e) {
193	      return oauthErrorResponse(e, PUBLIC_CORS_HEADERS);
194	    }
195	  }
196	
197	  return {
198	    config: cfg,
199	    resolveMcpContext: resolver.resolveMcpContext,
200	    oauth: {
201	      protectedResourceMetadata: () => protectedResourceMetadata(ctx),
202	      authorizationServerMetadata: () => authorizationServerMetadata(ctx),
203	      validateAuthorize: (raw: RawParams) => authorize.validateAuthorizeRequest(raw),
204	      buildClientRedirect: authorize.buildClientRedirect,
205	      decision: consent.handleConsentDecision,
206	      token,
207	      register,
208	      revoke,
209	      csrfTokenFor: (user) => csrf.csrfTokenFor(user),
210	      listGrantsForUser: grants.listGrantsForUser,
211	      revokeGrant: grants.revokeGrant,
212	      revokeAllGrantsForApp: grants.revokeAllGrantsForApp,
213	    },
214	    mcp: (handlerOpts) => createMcpHandler(ctx, resolver.resolveMcpContext, handlerOpts),
215	    store,
216	    assertCsrf: (req, user) => csrf.assertCsrf(req, user),
217	    requireUser: host.requireUser,
218	    contextFromUser: host.contextFromUser,
219	    hostMutation: host.hostMutation,
220	  };
221	}
