215	function parse<T>(schema: z.ZodType<T>, input: unknown): T {
216	  const r = schema.safeParse(input);
217	  if (!r.success) {
218	    throw new ContourError("INVALID_INPUT", "Request failed schema validation", {
219	      issues: r.error.issues.slice(0, 10).map((i) => ({
220	        code: "INVALID_INPUT",
221	        path: i.path.join(".") || "$",
222	        message: i.message,
223	      })),
224	    });
225	  }
226	  return r.data;
227	}
