251	  function requireScope(ctx: VerifiedContext, scope: Scope) {
252	    if (!ctx.scopes.has(scope)) throw new ContourError("FORBIDDEN", `Missing scope ${scope}`);
253	  }
254	
255	  function requireHost(ctx: VerifiedContext) {
256	    if (ctx.channel !== "host") throw new ContourError("FORBIDDEN", "This operation is only available in the host app");
