285	    const owner = ownerOf(ctx);
286	    const defaultSnap = (revision: number, source: ViewSnapshot["source"], reason?: string): ViewSnapshot => ({
287	      surfaceId: manifest.surfaceId,
288	      revision,
289	      policyVersion: manifest.policyVersion,
290	      config: manifest.defaultConfig,
291	      configHash: hashJson(manifest.defaultConfig),
292	      source,
293	      ...(reason ? { fallbackReason: reason } : {}),
294	    });
