375	  async function readComponentData(ctx: VerifiedContext, readerId: string, input: unknown) {
376	    requireScope(ctx, "data:read");
377	    await requireAgentAccess(ctx);
378	    const membership = await requireMembership(ctx);
379	    if (!membership.dataAccess) throw new ContourError("FORBIDDEN", "Data access has been revoked for this user");
380	    const manifest = manifestFor(ctx);
381	    const parsedId = parse(z.string().min(1).max(64).regex(/^[a-z0-9._-]+$/), readerId);
382	    const component = manifest.components.find((c) => c.readerId === parsedId);
383	    const reader = opts.readers.get(parsedId);
384	    if (!component || !reader) throw new ContourError("NOT_FOUND", "Unknown reader for this surface");
385	    requireScope(ctx, reader.requiredScope);
386	    await rateLimit(ctx, "read", 60);
387	    const typed = parse(reader.inputSchema, input ?? {});
388	    const timeoutMs = opts.readerTimeoutMs ?? 5000;
389	    const data = await Promise.race([
390	      reader.read(ctx, typed),
391	      new Promise<never>((_, rej) => setTimeout(() => rej(new ContourError("INTERNAL", "Reader timed out")), timeoutMs)),
392	    ]);
393	    const size = JSON.stringify(data).length;
394	    if (size > (opts.maxReaderOutputBytes ?? 64_000)) throw new ContourError("INTERNAL", "Reader output exceeded the size limit");
395	    return {
396	      readerId: reader.id,
397	      componentId: component.id,
398	      semanticRole: component.semanticRole,
399	      description: reader.description,
400	      fields: reader.fields,
401	      untrustedContent: true,
402	      data,
403	    };
404	  }
