424	  async function proposeView(ctx: VerifiedContext, rawRequest: unknown): Promise<ProposeResult> {
425	    const started = Date.now();
426	    requireScope(ctx, "view:propose");
427	    await requireAgentAccess(ctx);
428	    const membership = await requireMembership(ctx);
429	    const manifest = manifestFor(ctx);
430	    const policy = opts.policies[manifest.surfaceId];
431	    const req = parse(ProposeRequestSchema, rawRequest) as ProposeRequest;
432	    if (req.surfaceId !== ctx.surfaceId) throw new ContourError("FORBIDDEN", "Surface is not authorized for this grant");
433	    if (req.note && req.note.length > manifest.limits.maxNoteLength) throw new ContourError("INVALID_INPUT", "Note too long");
434	    await rateLimit(ctx, "propose", 10);
435	
436	    const owner = ownerOf(ctx);
437	    const requestHash = hashJson({ ...req, requestId: undefined });
438	
439	    // Idempotent replay of an identical request.
440	    const existing = await store.findProposalByRequest(owner, req.requestId);
441	    if (existing) {
442	      if (existing.requestHash !== requestHash) {
443	        throw new ContourError("IDEMPOTENCY_CONFLICT", "requestId was already used with a different payload");
444	      }
445	      const p = await expireIfNeeded(owner, existing);
446	      return {
447	        outcome: "READY",
448	        proposalId: p.id,
449	        status: p.status,
450	        baseRevision: p.baseRevision,
451	        changes: p.changes,
452	        rationale: p.rationale,
453	        previewUrl: `${opts.appUrl}/preview/${p.id}`,
454	        expiresAt: p.expiresAt,
455	        decisionId: p.decisionId,
456	        creditConsumed: false,
457	      };
458	    }
459	
460	    const snapshot = await loadSnapshot(ctx, manifest);
461	    if (req.baseRevision !== snapshot.revision) {
462	      throw new ContourError("STALE_REVISION", "The view changed since baseRevision; read it again", {
463	        currentRevision: snapshot.revision,
464	      });
465	    }
466	
467	    const decisionId = randomUUID();
468	    const jobId = randomUUID();
469	    const prefs = await store.getPreferences(owner);
470	    const inputs: Record<string, JsonValue> = {
471	      task: req.task.id,
472	      expertise: req.expertise.level,
473	      preferences: (req.preferences ?? {}) as Record<string, JsonValue>,
474	      noteProvided: Boolean(req.note),
475	      pins: prefs.pins.length,
476	      baseRevision: req.baseRevision,
477	      source: "explicit",
478	    };
479	    const baseEvent = {
480	      id: decisionId,
481	      jobId,
482	      owner,
483	      clientId: ctx.clientId,
484	      channel: ctx.channel,
485	      manifestVersion: manifest.manifestVersion,
486	      policyVersion: manifest.policyVersion,
487	      confidenceFloor: opts.confidenceFloor,
488	      inputs,
489	      assumptions: [] as string[],
490	    };
491	
492	    // Deterministic clarification before any paid work.
493	    const task = manifest.tasks.find((t) => t.id === req.task.id);
494	    const expertise = manifest.expertiseLevels.find((e) => e.id === req.expertise.level);
495	    if (!task || !expertise || !policy?.taskLayouts[req.task.id]) {
496	      const question = !task
497	        ? "Which supported task are you working on?"
498	        : "Which supported expertise level fits you for this task?";
499	      await store.recordDecision({
500	        ...baseEvent,
501	        modelVersion: null,
502	        candidateIds: [],
503	        candidateHashes: {},
504	        selectedId: "ASK",
505	        distribution: null,
506	        confidence: null,
507	        validation: "not_run",
508	        validationRules: [],
509	        outcome: "asked",
510	        outcomeReason: !task ? "unsupported_task" : "unsupported_expertise",
511	        providerStatus: "skipped",
512	        providerLatencyMs: null,
513	        totalLatencyMs: Date.now() - started,
514	        inputTokens: null,
515	        outputTokens: null,
516	        providerCost: null,
517	        currency: null,
518	        rationale: null,
519	        proposalId: null,
520	      });
521	      return {
522	        outcome: "ASK",
523	        question,
524	        supportedChoices: { task: manifest.tasks.map((t) => t.id), expertise: manifest.expertiseLevels.map((e) => e.id) },
525	        decisionId,
526	      };
527	    }
528	
529	    // Reserve one prepaid credit for this adaptation job.
530	    const reservation = await store.reserveCredit(owner, jobId);
531	    if (!reservation.ok) {
532	      throw new ContourError("PAYMENT_REQUIRED", "No adaptation credit available. Buy one in the host app.", {
533	        billingUrl: `${opts.appUrl}/billing`,
534	      });
535	    }
536	
537	    let released = false;
538	    const release = async () => {
539	      if (!released) {
540	        released = true;
541	        await store.releaseCredit(jobId);
542	      }
543	    };
544	
545	    try {
546	      const gen = generateCandidates(manifest, policy, {
547	        task: req.task.id,
548	        preferences: req.preferences ?? {},
549	        pins: prefs.pins,
550	      });
551	      const candidates = gen.candidates;
552	      const candidateHashes = Object.fromEntries(candidates.map((c) => [c.id, c.configHash]));
553	      const allIds = [...candidates.map((c) => c.id), "KEEP", "ASK"];
554	
555	      if (candidates.length === 0) {
556	        await release();
557	        const reason = gen.pinConflicts.length ? "pin_conflict" : "no_valid_candidates";
558	        await store.recordDecision({
559	          ...baseEvent,
560	          modelVersion: null,
561	          candidateIds: allIds,
562	          candidateHashes,
563	          selectedId: "ASK",
564	          distribution: null,
565	          confidence: null,
566	          validation: "failed",
567	          validationRules: gen.rejected.flatMap((r) => r.issues.map((i) => i.code)).slice(0, 20),
568	          outcome: "asked",
569	          outcomeReason: reason,
570	          providerStatus: "skipped",
571	          providerLatencyMs: null,
572	          totalLatencyMs: Date.now() - started,
573	          inputTokens: null,
574	          outputTokens: null,
575	          providerCost: null,
576	          currency: null,
577	          rationale: null,
578	          proposalId: null,
579	        });
580	        return {
581	          outcome: "ASK",
582	          question:
583	            reason === "pin_conflict"
584	              ? `Your manual pins conflict with every approved layout for this task (${gen.pinConflicts
585	                  .slice(0, 2)
586	                  .map((i) => i.message)
587	                  .join("; ")}). Unpin a component or choose another task?`
588	              : "No approved layout fits these preferences. Choose another task or preference?",
589	          supportedChoices: { task: manifest.tasks.map((t) => t.id), unpin: prefs.pins.map((p) => p.componentId) },
590	          decisionId,
591	        };
592	      }
593	
594	      const matchesCurrent = candidates.find((c) => configsEqual(c.config, snapshot.config))?.id ?? null;
595	      const selection = await selector.select({
596	        surface: { label: manifest.label, description: manifest.description },
597	        task,
598	        expertise,
599	        preferences: req.preferences ?? {},
600	        note: req.note,
601	        current: {
602	          summary: describeCurrent(manifest, snapshot.config),
603	          matchesCandidate: matchesCurrent,
604	        },
605	        candidates: candidates.map((c) => ({ id: c.id, label: c.label, summary: c.summary })),
606	      });
607	
608	      // Decision policy: KEEP on any provider problem, unknown choice, or low confidence.
609	      let outcome: "READY" | "KEEP" | "ASK" = "KEEP";
610	      let reason = "";
611	      let chosen: Candidate | undefined;
612	      if (selection.status !== "ok") {
613	        reason = `provider_${selection.status}`;
614	      } else if (selection.choice === "KEEP") {
615	        reason = "model_keep";
616	      } else if (selection.choice === "ASK") {
617	        outcome = "ASK";
618	        reason = "model_ask";
619	      } else if ((selection.confidence ?? 0) < opts.confidenceFloor) {
620	        reason = "low_confidence";
621	      } else {
622	        chosen = candidates.find((c) => c.id === selection.choice);
623	        if (!chosen) reason = "unknown_choice";
624	        else if (configsEqual(chosen.config, snapshot.config)) {
625	          reason = "already_current";
626	          chosen = undefined;
627	        } else outcome = "READY";
628	      }
629	
630	      const usageBase = {
631	        modelVersion: selection.modelVersion,
632	        providerLatencyMs: selection.providerLatencyMs,
633	        inputTokens: selection.usage?.inputTokens ?? null,
634	        outputTokens: selection.usage?.outputTokens ?? null,
635	        providerCost: selection.cost ?? null,
636	        currency: selection.currency ?? null,
637	      };
638	      await store.recordUsage({
639	        jobId,
640	        owner,
641	        provider: selector.provider,
642	        modelVersion: selection.modelVersion,
643	        usage: { inputTokens: usageBase.inputTokens, outputTokens: usageBase.outputTokens, latencyMs: selection.providerLatencyMs },
644	        cost: usageBase.providerCost,
645	        currency: usageBase.currency,
646	        status: selection.status,
647	      });
648	
649	      if (outcome !== "READY" || !chosen) {
650	        await release();
651	        await store.recordDecision({
652	          ...baseEvent,
653	          ...usageBase,
654	          candidateIds: allIds,
655	          candidateHashes,
656	          selectedId: selection.choice ?? null,
657	          distribution: selection.distribution ?? null,
658	          confidence: selection.confidence ?? null,
659	          validation: "passed",
660	          validationRules: [],
661	          outcome: outcome === "ASK" ? "asked" : "kept",
662	          outcomeReason: reason,
663	          providerStatus: selection.status,
664	          totalLatencyMs: Date.now() - started,
665	          rationale: null,
666	          proposalId: null,
667	        });
668	        if (outcome === "ASK") {
669	          return {
670	            outcome: "ASK",
671	            question: "Your stated context is ambiguous. Which task and expertise level should this view serve?",
672	            supportedChoices: {
673	              task: manifest.tasks.map((t) => t.id),
674	              expertise: manifest.expertiseLevels.map((e) => e.id),
675	              density: ["comfortable", "compact"],
676	            },
677	            decisionId,
678	          };
679	        }
680	        return { outcome: "KEEP", reason: keepMessage(reason), decisionId, currentRevision: snapshot.revision };
681	      }
682	
683	      // Validate the complete selected result once more before persisting.
684	      const final = validateViewConfig(manifest, chosen.config, { pins: prefs.pins });
685	      if (!final.ok) throw new ContourError("INVALID_CONFIG", "Selected candidate failed validation", { issues: final.issues });
686	      const changes = diffConfigs(manifest, snapshot.config, final.config);
687	      const rationale = buildRationale(task.label, expertise.label, chosen, changes, req.preferences ?? {}, selection.confidence);
688	      const expiresAt = new Date(now().getTime() + manifest.limits.proposalTtlSeconds * 1000).toISOString();
689	
690	      const created = await store.createProposal({
691	        tenant_id: owner.tenantId,
692	        app_id: owner.appId,
693	        subject_id: owner.subjectId,
694	        surface_id: owner.surfaceId,
695	        client_id: ctx.clientId,
696	        base_revision: snapshot.revision,
697	        manifest_version: manifest.manifestVersion,
698	        policy_version: manifest.policyVersion,
699	        role_version: membership.roleVersion,
700	        config: final.config as unknown as JsonValue,
701	        config_hash: chosen.configHash,
702	        candidate_id: chosen.id,
703	        task: task.id,
704	        expertise: expertise.id,
705	        preferences: (req.preferences ?? {}) as Record<string, JsonValue>,
706	        changes: changes as unknown as JsonValue,
707	        rationale,
708	        decision_id: decisionId,
709	        job_id: jobId,
710	        request_id: req.requestId,
711	        request_hash: requestHash,
712	        expires_at: expiresAt,
713	      });
714	      if (!created.ok) {
715	        await release();
