718	          created.code === "IDEMPOTENCY_CONFLICT" ? "requestId reused with a different payload" : "Could not persist the proposal",
719	        );
720	      }
721	      if (created.replayed) {
722	        // A concurrent identical request already persisted (and paid for) this proposal.
723	        await release();
724	      }
725	      released = true; // credit consumed inside the proposal transaction
726	      const proposalId = String(created.proposalId);
727	      await store.recordDecision({
728	        ...baseEvent,
729	        ...usageBase,
730	        candidateIds: allIds,
731	        candidateHashes,
732	        selectedId: chosen.id,
733	        distribution: selection.distribution ?? null,
734	        confidence: selection.confidence ?? null,
735	        validation: "passed",
736	        validationRules: final.rules,
737	        outcome: "previewed",
738	        outcomeReason: null,
739	        providerStatus: selection.status,
740	        totalLatencyMs: Date.now() - started,
741	        rationale,
742	        proposalId,
743	      });
744	      return {
745	        outcome: "READY",
746	        proposalId,
747	        status: "READY",
748	        baseRevision: snapshot.revision,
749	        changes,
750	        rationale,
