764	  async function getPreview(ctx: VerifiedContext, proposalId: string): Promise<PreviewData> {
765	    requireHost(ctx);
766	    await requireMembership(ctx);
767	    const manifest = manifestFor(ctx);
768	    const owner = ownerOf(ctx);
769	    const id = parse(z.uuid(), proposalId);
770	    let p = await store.getProposal(owner, id);
771	    if (!p) throw new ContourError("NOT_FOUND", "Proposal not found");
772	    p = await expireIfNeeded(owner, p);
773	    const current = await loadSnapshot(ctx, manifest);
774	    const prefs = await store.getPreferences(owner);
775	    let state: PreviewState = "ready";
776	    let stateReason: string | null = null;
777	    if (p.status === "APPLIED") state = "applied";
778	    else if (p.status === "REJECTED") state = "rejected";
779	    else if (p.status === "EXPIRED") {
780	      state = "expired";
781	      stateReason = "This proposal expired before it was accepted.";
782	    }
783	    else if (p.status === "STALE") {
784	      state = "stale";
785	      stateReason = "Your view changed after this proposal was made.";
786	    }
787	    else if (p.status === "INVALID") {
788	      state = "invalid";
789	      stateReason = "This proposal no longer passes company policy.";
790	    }
791	    else {
792	      const membership = await requireMembership(ctx);
793	      const valid = validateViewConfig(manifest, p.config, { pins: prefs.pins });
794	      if (p.manifestVersion !== manifest.manifestVersion || p.policyVersion !== manifest.policyVersion || String(membership.roleVersion) !== String(p.roleVersion)) {
795	        await store.setProposalStatus(owner, p.id, "READY", "INVALID", "manifest, policy or role changed");
796	        state = "invalid";
797	        stateReason = "The screen, its policy, or your role changed after this proposal was made.";
798	      } else if (!valid.ok) {
799	        await store.setProposalStatus(owner, p.id, "READY", "INVALID", "failed validation at preview");
800	        state = "invalid";
801	        stateReason = `This proposal no longer passes validation: ${valid.issues[0]?.message ?? "unknown rule"}.`;
802	      } else if (hashJson(valid.config) !== p.configHash) {
803	        await store.setProposalStatus(owner, p.id, "READY", "INVALID", "hash mismatch at preview");
804	        state = "invalid";
805	        stateReason = "The stored proposal does not match its recorded hash.";
806	      } else if (current.revision !== p.baseRevision) {
807	        await store.setProposalStatus(owner, p.id, "READY", "STALE", "base revision changed");
808	        state = "stale";
809	        stateReason = `Your view changed (now revision ${current.revision}) after this proposal was made for revision ${p.baseRevision}.`;
810	      }
811	    }
812	    return {
813	      proposal: { ...p, status: state === "invalid" ? "INVALID" : state === "stale" ? "STALE" : p.status },
814	      state,
815	      stateReason,
816	      current,
817	      proposed: p.config,
818	      changes: diffConfigs(manifest, current.config, p.config),
819	      pins: prefs.pins,
820	    };
821	  }
