823	  async function applyProposal(ctx: VerifiedContext, raw: unknown) {
824	    requireHost(ctx);
825	    const membership = await requireMembership(ctx);
826	    const manifest = manifestFor(ctx);
827	    const owner = ownerOf(ctx);
828	    const input = parse(ApplySchema, raw);
829	    const p = await store.getProposal(owner, input.proposalId);
830	    if (!p) throw new ContourError("NOT_FOUND", "Proposal not found");
831	    const prefs = await store.getPreferences(owner);
832	    if (p.status === "READY") {
833	      const valid = validateViewConfig(manifest, p.config, { pins: prefs.pins });
834	      if (!valid.ok) {
835	        await store.setProposalStatus(owner, p.id, "READY", "INVALID", "failed validation at commit");
836	        throw new ContourError("INVALID_CONFIG", "The proposal no longer passes validation", { issues: valid.issues });
837	      }
838	      if (hashJson(valid.config) !== p.configHash || input.configHash !== p.configHash) {
839	        throw new ContourError("HASH_MISMATCH", "The approved configuration does not match the stored proposal");
840	      }
841	      if (String(membership.roleVersion) !== String(p.roleVersion)) {
842	        await store.setProposalStatus(owner, p.id, "READY", "INVALID", "role changed");
843	        throw new ContourError("INCOMPATIBLE_MANIFEST", "Your role changed since this proposal was made");
844	      }
845	    }
846	    const result = await store.applyProposal({
847	      proposal_id: p.id,
848	      tenant_id: owner.tenantId,
849	      app_id: owner.appId,
850	      subject_id: owner.subjectId,
851	      surface_id: owner.surfaceId,
852	      config_hash: input.configHash,
853	      manifest_version: manifest.manifestVersion,
854	      policy_version: manifest.policyVersion,
855	      idempotency_key: input.idempotencyKey,
856	      request_hash: hashJson({ op: "apply", proposalId: p.id, configHash: input.configHash }),
857	      default_config: manifest.defaultConfig as unknown as JsonValue,
858	      default_hash: hashJson(manifest.defaultConfig),
859	      history_limit: manifest.limits.historyLimit,
860	      // Fresh role version from the membership re-check above. Schema-template
861	      // installs compare it in SQL; the public (Acme) RPC ignores it.
862	      role_version: membership.roleVersion,
863	    });
864	    return mapRpc(result) as { ok: true; revision: number; proposalId: string; replayed?: boolean };
865	  }
