879	  async function undo(ctx: VerifiedContext, raw: unknown) {
880	    requireHost(ctx);
881	    const membership = await requireMembership(ctx);
882	    const manifest = manifestFor(ctx);
883	    const owner = ownerOf(ctx);
884	    const input = parse(SnapshotOpSchema, raw);
885	    const active = await store.getActiveView(owner);
886	    if ((active?.revision ?? 0) !== input.expectedRevision) {
887	      throw new ContourError("STALE_REVISION", "The view changed; reload and try again", { currentRevision: active?.revision ?? 0 });
888	    }
889	    if (!active || active.parentRevision === null) {
890	      throw new ContourError("INCOMPATIBLE_SNAPSHOT", "There is no earlier view to restore");
891	    }
892	    const target = await store.getHistoryEntry(owner, active.parentRevision);
893	    if (!target) throw new ContourError("INCOMPATIBLE_SNAPSHOT", "The earlier view is outside the retained history");
894	    const prefs = await store.getPreferences(owner);
895	    const valid = validateViewConfig(manifest, target.config, { pins: prefs.pins });
896	    if (!valid.ok || target.manifestVersion !== manifest.manifestVersion) {
897	      throw new ContourError(
898	        "INCOMPATIBLE_SNAPSHOT",
899	        "Your previous layout is no longer compatible with the current screen, your access, or your pins, so it cannot be restored. Unpin or reset to the default instead.",
900	        { issues: valid.ok ? [] : valid.issues },
901	      );
902	    }
903	    const result = await store.commitSnapshot({
904	      operation: "undo",
905	      tenant_id: owner.tenantId,
906	      app_id: owner.appId,
907	      subject_id: owner.subjectId,
908	      surface_id: owner.surfaceId,
909	      expected_revision: input.expectedRevision,
910	      parent_revision: target.parentRevision,
911	      restored_from: target.revision,
912	      config: valid.config as unknown as JsonValue,
913	      config_hash: hashJson(valid.config),
914	      manifest_version: manifest.manifestVersion,
915	      policy_version: manifest.policyVersion,
916	      idempotency_key: input.idempotencyKey,
917	      request_hash: hashJson({ op: "undo", expected: input.expectedRevision }),
918	      default_config: manifest.defaultConfig as unknown as JsonValue,
919	      default_hash: hashJson(manifest.defaultConfig),
920	      history_limit: manifest.limits.historyLimit,
921	      role_version: membership.roleVersion,
922	    });
923	    return mapRpc(result) as { ok: true; revision: number };
924	  }
