929	    const manifest = manifestFor(ctx);
930	    const owner = ownerOf(ctx);
931	    const input = parse(SnapshotOpSchema, raw);
932	    const result = await store.commitSnapshot({
933	      operation: "reset",
934	      tenant_id: owner.tenantId,
935	      app_id: owner.appId,
936	      subject_id: owner.subjectId,
937	      surface_id: owner.surfaceId,
938	      expected_revision: input.expectedRevision,
939	      parent_revision: input.expectedRevision,
940	      restored_from: null,
941	      config: manifest.defaultConfig as unknown as JsonValue,
942	      config_hash: hashJson(manifest.defaultConfig),
943	      manifest_version: manifest.manifestVersion,
944	      policy_version: manifest.policyVersion,
945	      idempotency_key: input.idempotencyKey,
946	      request_hash: hashJson({ op: "reset", expected: input.expectedRevision }),
947	      default_config: manifest.defaultConfig as unknown as JsonValue,
948	      default_hash: hashJson(manifest.defaultConfig),
949	      history_limit: manifest.limits.historyLimit,
950	      role_version: membership.roleVersion,
951	    });
952	    return mapRpc(result) as { ok: true; revision: number };
953	  }
954	
955	  async function getSnapshot(ctx: VerifiedContext): Promise<ViewSnapshot> {
956	    requireScope(ctx, "view:read");
957	    await requireMembership(ctx);
958	    return loadSnapshot(ctx, manifestFor(ctx));
959	  }
960	
961	  async function getPreferences(ctx: VerifiedContext) {
962	    requireScope(ctx, "view:read");
963	    await requireMembership(ctx);
964	    return store.getPreferences(ownerOf(ctx));
965	  }
