967	  async function updatePreferences(ctx: VerifiedContext, raw: unknown) {
968	    requireHost(ctx);
969	    await requireMembership(ctx);
970	    const manifest = manifestFor(ctx);
971	    const prefs = parse(PreferencesSchema, raw) as UserPreferences;
972	    for (const pin of prefs.pins) {
973	      const spec = manifest.components.find((c) => c.id === pin.componentId);
974	      if (!spec) throw new ContourError("INVALID_INPUT", `Unknown component ${pin.componentId}`);
975	      if (spec.locked) throw new ContourError("INVALID_INPUT", `${spec.id} is locked by company policy`);
976	      if (pin.regionId && !spec.allowedRegions.includes(pin.regionId)) throw new ContourError("INVALID_INPUT", `${spec.id} cannot be pinned to ${pin.regionId}`);
977	      if (pin.variantId && !spec.variants.includes(pin.variantId)) throw new ContourError("INVALID_INPUT", `Unknown variant ${pin.variantId}`);
978	      if (pin.visible === false && spec.required) throw new ContourError("INVALID_INPUT", `${spec.id} is required and cannot be pinned hidden`);
979	    }
980	    if (new Set(prefs.pins.map((p) => p.componentId)).size !== prefs.pins.length) {
981	      throw new ContourError("INVALID_INPUT", "Only one pin per component");
982	    }
983	    await store.savePreferences(ownerOf(ctx), prefs);
984	    return prefs;
985	  }
