987	  async function getHistory(ctx: VerifiedContext) {
988	    requireHost(ctx);
989	    await requireMembership(ctx);
990	    const manifest = manifestFor(ctx);
991	    const entries = await store.listHistory(ownerOf(ctx), manifest.limits.historyLimit);
992	    return entries.map((e) => ({
993	      revision: e.revision,
