1002	  async function listProposals(ctx: VerifiedContext, limit = 10) {
1003	    requireHost(ctx);
1004	    await requireMembership(ctx);
1005	    const owner = ownerOf(ctx);
1006	    const list = await store.listProposals(owner, Math.min(limit, 50));
1007	    return Promise.all(list.map((p) => expireIfNeeded(owner, p)));
1008	  }
1009	
1010	  async function listDecisions(ctx: VerifiedContext, limit = 20) {
1011	    requireHost(ctx);
1012	    await requireMembership(ctx);
1013	    return store.listDecisions(ownerOf(ctx), Math.min(limit, 100));
1014	  }
1015	
1016	  async function creditBalance(ctx: VerifiedContext) {
1017	    await requireMembership(ctx);
1018	    return store.creditBalance(ownerOf(ctx));
1019	  }
1020	
1021	  return {
1022	    describeSurface,
1023	    readComponentData,
1024	    proposeView,
1025	    getView,
1026	    getPreview,
1027	    applyProposal,
1028	    rejectProposal,
1029	    undo,
1030	    reset,
1031	    getSnapshot,
1032	    getPreferences,
1033	    updatePreferences,
1034	    getHistory,
1035	    listProposals,
1036	    listDecisions,
1037	    creditBalance,
1038	    manifestFor,
1039	  };
1040	}
1041	
1042	export type AdaptiveBroker = ReturnType<typeof createAdaptiveBroker>;
1043	
1044	function mapRpc(result: RpcResult) {
1045	  if (result.ok) return result;
1046	  const code = String(result.code ?? "INTERNAL");
1047	  const messages: Record<string, string> = {
1048	    NOT_FOUND: "Proposal not found",
1049	    PROPOSAL_NOT_READY: `This proposal can no longer be applied (status ${String(result.status ?? "unknown")})`,
1050	    EXPIRED_PROPOSAL: "This proposal expired; request a new one",
1051	    HASH_MISMATCH: "The approved configuration does not match the stored proposal",
1052	    FORBIDDEN: "You no longer have access to this surface",
1053	    INCOMPATIBLE_MANIFEST: "The screen, its policy, or your role changed since this proposal was made",
1054	    STALE_REVISION: "Your view changed in another tab or session; request a new proposal",
1055	    IDEMPOTENCY_CONFLICT: "This request key was already used for a different request",
1056	    INVALID_INPUT: "Invalid request",
1057	  };
1058	  const known = [
1059	    "NOT_FOUND",
1060	    "PROPOSAL_NOT_READY",
1061	    "EXPIRED_PROPOSAL",
1062	    "HASH_MISMATCH",
1063	    "FORBIDDEN",
1064	    "INCOMPATIBLE_MANIFEST",
1065	    "STALE_REVISION",
1066	    "IDEMPOTENCY_CONFLICT",
1067	    "INVALID_INPUT",
1068	  ] as const;
1069	  const c = (known as readonly string[]).includes(code) ? (code as (typeof known)[number]) : "INTERNAL";
1070	  throw new ContourError(c, messages[c] ?? "Commit failed", {
1071	    ...(typeof result.currentRevision === "number" ? { currentRevision: result.currentRevision } : {}),
1072	    ...(result.status ? { status: result.status } : {}),
1073	  });
1074	}
