1076	function describeCurrent(manifest: SurfaceManifest, config: ViewConfig): string {
1077	  const parts = config.placements.filter((p) => p.visible).map((p) => `${p.componentId}=${p.variantId}@${p.regionId}`);
1078	  const tpl = manifest.templates.find((t) => t.id === config.templateId)?.label ?? config.templateId;
1079	  return `Template ${tpl}; density ${config.densityToken.replace("density.", "")}; ${parts.join(", ")}.`;
1080	}
1081	
1082	function keepMessage(reason: string): string {
1083	  switch (reason) {
1084	    case "provider_timeout":
1085	      return "The selector timed out, so your current view was kept.";
1086	    case "provider_error":
1087	    case "provider_malformed":
1088	      return "The selector was unavailable, so your current view was kept.";
1089	    case "provider_unconfigured":
1090	      return "No selection model is configured, so your current view was kept.";
1091	    case "low_confidence":
1092	      return "No candidate was a confident enough fit, so your current view was kept.";
1093	    case "already_current":
1094	      return "Your current view already matches the best fit.";
1095	    case "unknown_choice":
1096	      return "The selector returned an unknown choice, so your current view was kept.";
1097	    default:
1098	      return "Your current view is preferable or the change would add little.";
1099	  }
1100	}
1101	
1102	function buildRationale(
1103	  taskLabel: string,
1104	  expertiseLabel: string,
1105	  chosen: Candidate,
1106	  changes: ChangeItem[],
1107	  prefs: { density?: string; help?: string },
1108	  confidence: number | undefined,
1109	): string {
1110	  const top = changes.slice(0, 3).map((c) => c.summary.toLowerCase());
1111	  const density = prefs.density ? `Density follows your explicit ${prefs.density} preference.` : "No density preference was stated.";
1112	  const conf = confidence !== undefined ? ` Selector confidence ${confidence.toFixed(2)} (a fit judgment, not a guarantee).` : "";
1113	  return `${chosen.label} layout for "${taskLabel}" at ${expertiseLabel.toLowerCase()} level${
1114	    top.length ? `: ${top.join("; ")}` : ""
1115	  }. ${density}${conf}`;
1116	}
