1	/**
2	 * @contour/sdk/testing: a pure contract kit for a company's manifest, policy
3	 * and readers. No network, no database, no framework. Run it from a unit test
4	 * or a setup script to prove an integration honours the Contour contract.
5	 */
6	import type { ReaderDef } from "../core/broker";
7	import { generateCandidates, type CandidatePolicy } from "../core/candidates";
8	import { validateManifest } from "../core/registry";
9	import { AGENT_SCOPES, type DensityPreference, type SurfaceManifest, type ViewConfig } from "../core/types";
10	import { validateViewConfig } from "../core/validate";
11	
12	export type ContractReport = {
13	  ok: boolean;
14	  passed: number;
15	  failed: number;
16	  checks: { name: string; ok: boolean; detail?: string }[];
17	};
18	
19	type Check = { name: string; ok: boolean; detail?: string };
20	
21	const DENSITIES: readonly DensityPreference[] = ["comfortable", "compact"];
22	const UNKNOWN = "contour-contract-unknown";
23	
24	function messageOf(e: unknown): string {
25	  return e instanceof Error ? e.message : String(e);
26	}
27	
28	/** Runs one named check; a throw is a failure, never an exception for the caller. */
29	function check(checks: Check[], name: string, fn: () => string[] | string | null | void): void {
30	  try {
31	    const out = fn();
32	    const problems = Array.isArray(out) ? out : out ? [out] : [];
33	    checks.push(problems.length ? { name, ok: false, detail: problems.slice(0, 8).join("; ") } : { name, ok: true });
34	  } catch (e) {
35	    checks.push({ name, ok: false, detail: `threw: ${messageOf(e)}` });
36	  }
37	}
38	
39	function patchPlacement(config: ViewConfig, componentId: string, patch: Partial<ViewConfig["placements"][number]>): ViewConfig {
40	  return { ...config, placements: config.placements.map((p) => (p.componentId === componentId ? { ...p, ...patch } : p)) };
41	}
42	
43	/** Expects validation to fail and, when a code is given, to name that code. */
44	function expectRejected(manifest: SurfaceManifest, config: unknown, code?: string): string | null {
45	  const r = validateViewConfig(manifest, config);
46	  if (r.ok) return "was accepted";
47	  if (code && !r.issues.some((i) => i.code === code)) {
48	    return `was rejected without ${code} (got ${[...new Set(r.issues.map((i) => i.code))].join(", ")})`;
49	  }
50	  return null;
51	}
52	
53	export async function runContractKit(input: {
54	  manifest: SurfaceManifest;
55	  policy: CandidatePolicy;
56	  readers: ReadonlyMap<string, ReaderDef> | readonly ReaderDef[];
57	  componentIds: ReadonlySet<string> | readonly string[];
58	}): Promise<ContractReport> {
59	  const { manifest, policy } = input;
60	  const readers = new Map<string, ReaderDef>(
61	    input.readers instanceof Map ? input.readers : (input.readers as readonly ReaderDef[]).map((r) => [r.id, r] as const),
62	  );
63	  const componentIds = new Set<string>(input.componentIds);
64	  const checks: Check[] = [];
65	  const base = manifest.defaultConfig;
66	
67	  check(checks, "registration: manifest, readers and renderers", () =>
68	    validateManifest(manifest, { readerIds: new Set(readers.keys()), implementedComponentIds: componentIds }).map(
69	      (i) => `${i.code} ${i.path}: ${i.message}`,
70	    ),
71	  );
72	
73	  check(checks, "default config validates", () => {
74	    const r = validateViewConfig(manifest, base);
75	    return r.ok ? [] : r.issues.map((i) => `${i.code} ${i.path}`);
76	  });
77	
78	  check(checks, "readers: registered and agent-readable", () => {
79	    const problems: string[] = [];
80	    for (const c of manifest.components) {
81	      if (!c.readerId) continue;
82	      const reader = readers.get(c.readerId);
83	      if (!reader) {
84	        problems.push(`${c.id} references unregistered reader "${c.readerId}"`);
85	        continue;
86	      }
87	      if (!AGENT_SCOPES.includes(reader.requiredScope)) {
88	        problems.push(`reader "${reader.id}" requires scope "${reader.requiredScope}", which agents can never hold`);
89	      }
90	    }
91	    return problems;
92	  });
93	
94	  check(checks, "required components are visible in the default", () =>
95	    manifest.components
96	      .filter((c) => c.required)
97	      .filter((c) => base.placements.find((p) => p.componentId === c.id)?.visible !== true)
98	      .map((c) => `${c.id} is required but not visible in the default`),
99	  );
100	
101	  check(checks, "candidates: every task and density keeps required and locked components", () => {
102	    const problems: string[] = [];
103	    if (manifest.tasks.length === 0) return "the manifest declares no tasks";
104	    for (const task of manifest.tasks) {
105	      for (const density of DENSITIES) {
106	        const where = `task ${task.id}, density ${density}`;
107	        let result;
108	        try {
109	          result = generateCandidates(manifest, policy, { task: task.id, preferences: { density }, pins: [] });
110	        } catch (e) {
111	          problems.push(`${where}: ${messageOf(e)}`);
112	          continue;
113	        }
114	        if (result.candidates.length === 0) {
115	          problems.push(`${where}: no valid candidate (${result.rejected.map((r) => r.id).join(", ") || "none generated"})`);
116	          continue;
117	        }
118	        for (const cand of result.candidates) {
119	          const valid = validateViewConfig(manifest, cand.config);
120	          if (!valid.ok) problems.push(`${where}, ${cand.id}: ${valid.issues.map((i) => i.code).join(", ")}`);
121	          for (const spec of manifest.components) {
122	            const p = cand.config.placements.find((x) => x.componentId === spec.id);
123	            if (spec.required && p?.visible !== true) problems.push(`${where}, ${cand.id}: required ${spec.id} not visible`);
124	            if (spec.locked) {
125	              const d = base.placements.find((x) => x.componentId === spec.id);
126	              if (!p || !d || JSON.stringify(p) !== JSON.stringify(d)) problems.push(`${where}, ${cand.id}: locked ${spec.id} changed`);
127	            }
128	          }
129	        }
130	      }
131	    }
132	    return problems;
133	  });
134	
135	  const first = base?.placements?.[0];
136	
137	  check(checks, "closed schema: extra top-level key is rejected", () =>
138	    expectRejected(manifest, { ...base, [UNKNOWN]: true }, "INVALID_SHAPE"),
139	  );
140	
141	  check(checks, "closed schema: unknown variant is rejected", () => {
142	    if (!first) return "the default has no placements";
143	    const r = expectRejected(manifest, patchPlacement(base, first.componentId, { variantId: UNKNOWN }), "UNKNOWN_VARIANT");
144	    return r && `variant ${r}`;
145	  });
146	
147	  check(checks, "closed schema: unknown setting is rejected", () => {
148	    if (!first) return "the default has no placements";
149	    const r = expectRejected(
150	      manifest,
151	      patchPlacement(base, first.componentId, { settings: { ...first.settings, [UNKNOWN]: true } }),
152	      "UNKNOWN_SETTING",
153	    );
154	    return r && `setting ${r}`;
155	  });
156	
157	  check(checks, "closed schema: hiding a required component is rejected", () => {
158	    const spec = manifest.components.find((c) => c.required);
159	    if (!spec) return null; // nothing required, nothing to hide
160	    const r = expectRejected(manifest, patchPlacement(base, spec.id, { visible: false }), "REQUIRED_HIDDEN");
161	    return r && `hiding ${spec.id} ${r}`;
162	  });
163	
164	  check(checks, "closed schema: moving a locked component is rejected", () => {
165	    const spec = manifest.components.find((c) => c.locked);
166	    if (!spec) return null; // nothing locked, nothing to move
167	    const p = base.placements.find((x) => x.componentId === spec.id);
