173	  check(checks, "readers: input schema rejects an unknown key", () => {
174	    const problems: string[] = [];
175	    for (const reader of readers.values()) {
176	      const r = reader.inputSchema.safeParse({ [UNKNOWN]: true });
177	      if (r.success) problems.push(`reader "${reader.id}" accepts unknown keys; use z.strictObject`);
178	    }
179	    return problems;
180	  });
