1	import { z } from "zod";
2	import type {
3	  ComponentSpec,
4	  JsonValue,
5	  LayoutTemplate,
6	  ManualPin,
7	  Placement,
8	  SettingSchema,
9	  SurfaceManifest,
10	  ValidationIssue,
11	  ViewConfig,
12	} from "./types";
13	
14	/**
15	 * Deterministic validation of a full ViewConfig against a trusted manifest.
16	 *
17	 * Order (spec §5): closed structural schema → unknown keys/IDs → value
18	 * constraints → relational whole-result rules → manual pins. The model can
19	 * never waive a rule; every entry point (proposal creation, preview read,
20	 * commit, saved-view load) calls the same function.
21	 */
22	
23	const ID = z.string().min(1).max(64).regex(/^[a-z0-9][a-z0-9._-]*$/);
24	const SettingValue = z.union([z.string().max(128), z.number().finite(), z.boolean()]);
25	
26	export const PlacementSchema = z.strictObject({
27	  componentId: ID,
28	  regionId: ID,
29	  order: z.number().int().min(0).max(63),
30	  variantId: ID,
31	  visible: z.boolean(),
32	  settings: z.record(z.string().max(64), SettingValue).refine((o) => Object.keys(o).length <= 16, "too many settings"),
33	});
34	
35	export const ViewConfigSchema = z.strictObject({
36	  schemaVersion: z.literal("1"),
37	  manifestVersion: z.string().min(1).max(32),
38	  templateId: ID,
39	  densityToken: ID,
40	  placements: z.array(PlacementSchema).min(1).max(32),
41	});
