50	export type ValidationResult =
51	  | { ok: true; config: ViewConfig; rules: string[] }
52	  | { ok: false; issues: ValidationIssue[]; rules: string[] };
53	
54	export const VALIDATION_RULES = [
55	  "closed_schema",
56	  "manifest_version",
57	  "known_template",
58	  "known_token",
59	  "known_components",
60	  "complete_placements",
61	  "allowed_region",
62	  "known_variant",
63	  "settings_schema",
64	  "normalized_order",
65	  "required_visible",
66	  "locked_unchanged",
67	  "region_capacity_all_breakpoints",
68	  "dependencies",
69	  "manual_pins",
70	] as const;
71	
72	export function validateSettingValue(schema: SettingSchema, value: unknown): string | null {
73	  if ("enum" in schema) {
74	    return schema.enum.some((e) => e === value) ? null : `must be one of ${schema.enum.join(", ")}`;
75	  }
76	  switch (schema.type) {
77	    case "boolean":
78	      return typeof value === "boolean" ? null : "must be a boolean";
79	    case "integer":
80	      if (typeof value !== "number" || !Number.isInteger(value)) return "must be an integer";
81	      if (value < schema.minimum || value > schema.maximum) return `must be between ${schema.minimum} and ${schema.maximum}`;
82	      return null;
83	    case "string":
84	      if (typeof value !== "string") return "must be a string";
85	      if (value.length > schema.maxLength) return `must be at most ${schema.maxLength} characters`;
86	      if (schema.pattern && !new RegExp(schema.pattern).test(value)) return "has an invalid format";
87	      return null;
88	  }
89	}
90	
91	export function validateSettings(
92	  spec: ComponentSpec,
93	  settings: Record<string, JsonValue>,
94	  path: string,
95	): ValidationIssue[] {
96	  const issues: ValidationIssue[] = [];
97	  const props = spec.settingsSchema.properties;
98	  for (const key of Object.keys(settings)) {
99	    if (!Object.prototype.hasOwnProperty.call(props, key)) {
100	      issues.push({ code: "UNKNOWN_SETTING", path: `${path}.${key}`, message: `Setting "${key}" is not registered for ${spec.id}` });
101	    }
102	  }
103	  for (const key of spec.settingsSchema.required) {
104	    if (!Object.prototype.hasOwnProperty.call(settings, key)) {
105	      issues.push({ code: "MISSING_SETTING", path: `${path}.${key}`, message: `Setting "${key}" is required for ${spec.id}` });
106	    }
107	  }
108	  for (const [key, schema] of Object.entries(props)) {
109	    if (!Object.prototype.hasOwnProperty.call(settings, key)) continue;
110	    const err = validateSettingValue(schema, settings[key]);
111	    if (err) issues.push({ code: "INVALID_SETTING", path: `${path}.${key}`, message: `${spec.id}.${key} ${err}` });
112	  }
113	  return issues;
114	}
115	
116	function issue(code: string, path: string, message: string): ValidationIssue {
117	  return { code, path, message };
118	}
119	
120	export function validateViewConfig(
121	  manifest: SurfaceManifest,
122	  input: unknown,
123	  opts: { pins?: readonly ManualPin[] } = {},
124	): ValidationResult {
125	  const rules = [...VALIDATION_RULES];
126	  // 1. Closed structural schema.
127	  const parsed = ViewConfigSchema.safeParse(input);
128	  if (!parsed.success) {
129	    return {
130	      ok: false,
131	      rules,
132	      issues: parsed.error.issues.slice(0, 20).map((i) =>
133	        issue("INVALID_SHAPE", i.path.length ? i.path.join(".") : "$", i.message),
134	      ),
135	    };
136	  }
137	  const config = parsed.data as ViewConfig;
138	  const issues: ValidationIssue[] = [];
139	
140	  // 2. Known identifiers and versions.
141	  if (config.manifestVersion !== manifest.manifestVersion) {
142	    issues.push(issue("MANIFEST_VERSION_MISMATCH", "manifestVersion", `Expected ${manifest.manifestVersion}`));
143	  }
144	  const template = manifest.templates.find((t) => t.id === config.templateId);
145	  if (!template) issues.push(issue("UNKNOWN_TEMPLATE", "templateId", `Template "${config.templateId}" is not registered`));
146	  if (!manifest.tokenIds.includes(config.densityToken)) {
147	    issues.push(issue("UNKNOWN_TOKEN", "densityToken", `Token "${config.densityToken}" is not registered`));
148	  }
149	  if (config.placements.length > manifest.limits.maxPlacements) {
150	    issues.push(issue("TOO_MANY_PLACEMENTS", "placements", `At most ${manifest.limits.maxPlacements} placements`));
151	  }
152	
153	  const specs = new Map(manifest.components.map((c) => [c.id, c]));
154	  const seen = new Set<string>();
155	  config.placements.forEach((p, i) => {
156	    const path = `placements[${i}]`;
157	    const spec = specs.get(p.componentId);
158	    if (!spec) {
159	      issues.push(issue("UNKNOWN_COMPONENT", `${path}.componentId`, `Component "${p.componentId}" is not registered`));
160	      return;
161	    }
162	    if (seen.has(p.componentId)) {
163	      issues.push(issue("DUPLICATE_COMPONENT", `${path}.componentId`, `Component "${p.componentId}" appears more than once`));
164	    }
165	    seen.add(p.componentId);
166	    if (template && !template.regions.some((r) => r.id === p.regionId)) {
167	      issues.push(issue("UNKNOWN_REGION", `${path}.regionId`, `Region "${p.regionId}" is not in template ${template.id}`));
168	    } else if (!spec.allowedRegions.includes(p.regionId)) {
169	      issues.push(issue("REGION_NOT_ALLOWED", `${path}.regionId`, `${spec.id} may not be placed in "${p.regionId}"`));
170	    }
171	    if (!spec.variants.includes(p.variantId)) {
172	      issues.push(issue("UNKNOWN_VARIANT", `${path}.variantId`, `Variant "${p.variantId}" is not registered for ${spec.id}`));
173	    }
174	    issues.push(...validateSettings(spec, p.settings, `${path}.settings`));
175	  });
176	
177	  for (const spec of manifest.components) {
178	    if (!seen.has(spec.id)) {
179	      issues.push(issue("MISSING_COMPONENT", "placements", `Component "${spec.id}" must be represented (hidden optional components included)`));
180	    }
181	  }
182	
183	  // 3. Relational rules over the whole result.
184	  const byRegion = new Map<string, Placement[]>();
185	  for (const p of config.placements) {
186	    const list = byRegion.get(p.regionId) ?? [];
187	    list.push(p);
188	    byRegion.set(p.regionId, list);
189	  }
190	  for (const [regionId, list] of byRegion) {
191	    const orders = list.map((p) => p.order).sort((a, b) => a - b);
192	    if (orders.some((o, idx) => o !== idx)) {
193	      issues.push(issue("ORDER_NOT_NORMALIZED", `regions.${regionId}`, `Orders in "${regionId}" must be unique and contiguous from 0`));
194	    }
195	  }
196	
197	  const defaults = new Map(manifest.defaultConfig.placements.map((p) => [p.componentId, p]));
198	  config.placements.forEach((p, i) => {
199	    const spec = specs.get(p.componentId);
200	    if (!spec) return;
201	    const path = `placements[${i}]`;
202	    if (spec.required && !p.visible) {
203	      issues.push(issue("REQUIRED_HIDDEN", `${path}.visible`, `${spec.id} is required and cannot be hidden`));
204	    }
205	    if (spec.locked) {
206	      const d = defaults.get(spec.id);
207	      if (
208	        !d ||
209	        d.regionId !== p.regionId ||
210	        d.order !== p.order ||
211	        d.variantId !== p.variantId ||
212	        d.visible !== p.visible ||
213	        JSON.stringify(d.settings) !== JSON.stringify(p.settings)
214	      ) {
215	        issues.push(issue("LOCKED_CHANGED", path, `${spec.id} is locked by company policy and cannot be moved or changed`));
216	      }
217	    }
218	  });
219	
220	  if (template) issues.push(...checkCapacity(template, config.placements));
221	
222	  for (const dep of manifest.dependencies) {
223	    const p = config.placements.find((x) => x.componentId === dep.componentId);
224	    if (!p || !p.visible) continue;
225	    if (dep.whenVariants && !dep.whenVariants.includes(p.variantId)) continue;
226	    const req = config.placements.find((x) => x.componentId === dep.requiresVisible);
227	    if (!req || !req.visible) {
228	      issues.push(issue("DEPENDENCY_UNMET", `placements.${dep.componentId}`, dep.reason));
229	    }
230	  }
231	
232	  // 4. Manual pins.
233	  for (const [i, pin] of (opts.pins ?? []).entries()) {
234	    const p = config.placements.find((x) => x.componentId === pin.componentId);
235	    const path = `pins[${i}]`;
236	    if (!p) {
237	      issues.push(issue("PIN_UNKNOWN_COMPONENT", path, `Pinned component "${pin.componentId}" is not placed`));
238	      continue;
239	    }
240	    if (pin.regionId !== undefined && pin.regionId !== p.regionId) {
241	      issues.push(issue("PIN_VIOLATED", path, `${pin.componentId} is pinned to region "${pin.regionId}"`));
242	    }
243	    if (pin.visible !== undefined && pin.visible !== p.visible) {
244	      issues.push(issue("PIN_VIOLATED", path, `${pin.componentId} is pinned ${pin.visible ? "visible" : "hidden"}`));
245	    }
246	    if (pin.variantId !== undefined && pin.variantId !== p.variantId) {
247	      issues.push(issue("PIN_VIOLATED", path, `${pin.componentId} is pinned to variant "${pin.variantId}"`));
248	    }
249	  }
250	
251	  return issues.length ? { ok: false, issues: issues.slice(0, 50), rules } : { ok: true, config, rules };
252	}
253	
254	export function checkCapacity(template: LayoutTemplate, placements: readonly Placement[]): ValidationIssue[] {
255	  const issues: ValidationIssue[] = [];
256	  const visibleByRegion = new Map<string, number>();
257	  for (const p of placements) if (p.visible) visibleByRegion.set(p.regionId, (visibleByRegion.get(p.regionId) ?? 0) + 1);
258	  for (const bp of template.breakpoints) {
259	    for (const [regionId, count] of visibleByRegion) {
260	      const cap = bp.regionCapacity[regionId] ?? 0;
261	      if (count > cap) {
262	        issues.push(
263	          issue("REGION_CAPACITY", `regions.${regionId}`, `"${regionId}" holds ${cap} visible components at ${bp.id} width; ${count} requested`),
264	        );
265	      }
266	    }
267	  }
268	  return issues;
269	}
270	
271	/** Renumber orders inside each region to 0..n-1 preserving relative order. */
272	export function normalizeOrders(placements: Placement[]): Placement[] {
273	  const byRegion = new Map<string, Placement[]>();
274	  for (const p of placements) {
275	    const list = byRegion.get(p.regionId) ?? [];
276	    list.push(p);
277	    byRegion.set(p.regionId, list);
278	  }
279	  const out: Placement[] = [];
280	  for (const list of byRegion.values()) {
281	    list
282	      .slice()
283	      .sort((a, b) => a.order - b.order)
284	      .forEach((p, idx) => out.push({ ...p, order: idx }));
285	  }
286	  return out;
287	}
