1	import type { BreakpointId, LayoutTemplate, Placement, TemplateBreakpoint, ViewConfig } from "../core/types";
2	
3	const SAFE_ID = /^[A-Za-z0-9_-]+$/;
4	
5	export function sortedBreakpoints(template: LayoutTemplate): TemplateBreakpoint[] {
6	  return [...template.breakpoints].sort((a, b) => a.minWidth - b.minWidth);
7	}
8	
9	export type RegionBlock = { regionId: string; label: string; placements: Placement[] };
10	
11	/** Visible placements grouped by region, in the breakpoint's reading order, each sorted by `order`. */
12	export function regionBlocks(template: LayoutTemplate, bp: TemplateBreakpoint, config: ViewConfig): RegionBlock[] {
13	  const labels = new Map(template.regions.map((r) => [r.id, r.label]));
14	  const order = bp.regionOrder.length ? bp.regionOrder : template.regions.map((r) => r.id);
15	  return order
16	    .map((regionId) => ({
17	      regionId,
18	      label: labels.get(regionId) ?? regionId,
19	      placements: config.placements
20	        .filter((p) => p.visible && p.regionId === regionId)
21	        .sort((a, b) => a.order - b.order || a.componentId.localeCompare(b.componentId)),
22	    }))
23	    .filter((b) => b.placements.length > 0);
24	}
25	
26	export function regionOrdersDiffer(template: LayoutTemplate): boolean {
27	  const keys = new Set(template.breakpoints.map((b) => b.regionOrder.join("|")));
28	  return keys.size > 1;
29	}
30	
31	function clampSpan(span: number, columns: number) {
32	  return Math.max(1, Math.min(columns, Math.floor(span) || columns));
33	}
34	
35	function rulesFor(scope: string, bp: TemplateBreakpoint): string {
36	  const sel = `[data-cs="${scope}"]`;
37	  const cols = Math.max(1, Math.floor(bp.columns));
38	  let css = `${sel} .cs-grid{grid-template-columns:repeat(${cols},minmax(0,1fr));}`;
39	  for (const [region, span] of Object.entries(bp.regionSpan)) {
40	    if (!SAFE_ID.test(region)) continue;
41	    const s = clampSpan(span, cols);
42	    css += `${sel} .cs-region[data-region="${region}"]{grid-column:span ${s}/span ${s};}`;
43	  }
44	  return css;
45	}
46	
47	/**
48	 * Generates the grid CSS for a template from the company manifest (trusted,
49	 * reviewed metadata; identifiers are still allowlisted). Breakpoints use
50	 * viewport media queries with the manifest's `minWidth` values; previews pass
51	 * an override that pins a single breakpoint.
52	 */
53	export function surfaceCss(scope: string, template: LayoutTemplate, override?: BreakpointId): string {
54	  if (!SAFE_ID.test(scope)) return "";
55	  const bps = sortedBreakpoints(template);
56	  if (bps.length === 0) return "";
57	  if (override) return rulesFor(scope, bps.find((b) => b.id === override) ?? bps[bps.length - 1]);
58	  return bps
59	    .map((bp) => (bp.minWidth <= 0 ? rulesFor(scope, bp) : `@media (min-width:${Math.floor(bp.minWidth)}px){${rulesFor(scope, bp)}}`))
60	    .join("");
61	}
62	
63	/** Active breakpoint for a viewport width. */
