3	import { useEffect, useId, useRef, useState } from "react";
4	
5	export type ConnectAgentPanelProps = {
6	  /** Origin of Contour Cloud, e.g. "https://cloud.contour.example". With `projectId`, adds the Cloud link. */
7	  cloudUrl?: string;
8	  projectId?: string;
9	  /** Shown in the heading context and used to name the MCP server in the command. */
10	  projectName: string;
11	  /** The app's MCP endpoint, e.g. "https://app.example.com/api/mcp". */
12	  mcpUrl: string;
13	  className?: string;
14	};
15	
16	/** "Acme Ops" -> "acme-ops": a safe MCP server name for the shell command. */
17	function serverName(projectName: string): string {
18	  const slug = projectName
19	    .toLowerCase()
20	    .replace(/[^a-z0-9]+/g, "-")
21	    .replace(/^-+|-+$/g, "");
22	  return slug || "contour";
23	}
24	
25	/**
26	 * Tells a signed-in user how to connect an AI agent to this app. Unstyled
27	 * beyond its structure: every class starts with `contour-connect` so the host
28	 * styles it with its own CSS. Native button and link focus rings are left
29	 * untouched, so focus stays visible unless the host overrides them.
30	 */
31	export function ConnectAgentPanel({ cloudUrl, projectId, projectName, mcpUrl, className }: ConnectAgentPanelProps) {
32	  const headingId = useId();
33	  const [copied, setCopied] = useState(false);
34	  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
35	  useEffect(() => () => void (timer.current && clearTimeout(timer.current)), []);
36	
37	  const command = `claude mcp add --transport http ${serverName(projectName)} ${mcpUrl}`;
38	  const cloudHref =
39	    cloudUrl && projectId ? `${cloudUrl.replace(/\/+$/, "")}/link/start?project=${encodeURIComponent(projectId)}` : null;
40	
41	  async function copy() {
42	    try {
43	      await navigator.clipboard.writeText(command);
44	      setCopied(true);
45	      if (timer.current) clearTimeout(timer.current);
46	      timer.current = setTimeout(() => setCopied(false), 2000);
47	    } catch {
48	      setCopied(false);
49	    }
50	  }
51	
52	  return (
53	    <section className={className ? `contour-connect ${className}` : "contour-connect"} aria-labelledby={headingId}>
54	      <h2 id={headingId} className="contour-connect-heading">
55	        Connect your AI agent
56	      </h2>
57	      <p className="contour-connect-intro">
58	        Your agent can describe this screen, read data you can already see, and propose views you approve here. It can never save
59	        changes itself.
60	      </p>
61	      <div className="contour-connect-command">
62	        <pre className="contour-connect-code" tabIndex={0} aria-label={`Command to connect ${projectName}`}>
63	          <code>{command}</code>
64	        </pre>
65	        <button type="button" className="contour-connect-copy" onClick={copy}>
66	          {copied ? "Copied" : "Copy command"}
67	        </button>
68	        <span className="contour-connect-status" role="status" aria-live="polite">
69	          {copied ? "Command copied to the clipboard" : ""}
70	        </span>
71	      </div>
72	      {cloudHref ? (
73	        <p className="contour-connect-cloud">
74	          <a className="contour-connect-link" href={cloudHref}>
75	            Link through Contour Cloud
76	          </a>
77	        </p>
78	      ) : null}
79	    </section>
