2	import { NextResponse } from "next/server";
3	import { ALL_SCOPES, ContourError, type VerifiedContext } from "../../core/types";
4	import type { HostUser } from "../config";
5	import type { ServerContext } from "../context";
6	import type { Csrf } from "./csrf";
7	import { errorResponse } from "./http";
8	
9	const MAX_BODY = 32 * 1024;
