11	export function createHostRoute(ctx: ServerContext, csrf: Csrf) {
12	  /** The verified host session. Signed out is UNAUTHENTICATED; identity may also throw FORBIDDEN. */
13	  async function requireUser(): Promise<HostUser> {
14	    const user = await ctx.cfg.identity.currentUser();
15	    if (!user) throw new ContourError("UNAUTHENTICATED", "Sign in required");
16	    return user;
17	  }
18	
19	  /** Broker context for a verified host session: every scope, host channel. */
20	  function contextFromUser(u: HostUser, surfaceId: string = ctx.defaultSurface()): VerifiedContext {
21	    return {
22	      subjectId: u.subjectId,
23	      tenantId: u.tenantId,
24	      appId: ctx.cfg.appId,
25	      surfaceId,
26	      clientId: "host",
27	      grantRevision: "host-session",
28	      scopes: new Set(ALL_SCOPES),
29	      roleVersion: String(u.roleVersion),
30	      role: u.role,
31	      channel: "host",
32	    };
33	  }
34	
35	  /** Authenticated host-app mutation: verified session + same-origin + CSRF token. */
36	  async function hostMutation(request: Request, fn: (ctx: VerifiedContext, body: unknown) => Promise<unknown>) {
