1	#!/usr/bin/env node
2	import { spawn } from 'node:child_process';
3	import { readFile, realpath } from 'node:fs/promises';
4	import { createRequire } from 'node:module';
5	import { extname, isAbsolute, relative, resolve } from 'node:path';
6	import { fileURLToPath, pathToFileURL } from 'node:url';
7	
8	const self = fileURLToPath(import.meta.url);
9	const resultMarker = 'CONTOUR_CONTRACT_RESULT:';
10	
11	// Run imports in a separate Node process so TS loaders and react-server apply
12	// before SDK/host modules are loaded. Resolve both packages from the host app.
13	async function contractWorker(appDir, moduleFile, kitFile) {
14	  const { runContractKit } = await import(pathToFileURL(kitFile).href);
15	  if (typeof runContractKit !== 'function') throw new Error('runContractKit export is missing');
16	  const registration = await import(pathToFileURL(moduleFile).href);
17	  for (const name of ['manifest', 'policy', 'readers', 'componentIds']) {
18	    if (registration[name] === undefined) throw new Error(`Registration export missing: ${name}`);
19	  }
20	  const { manifest, policy, readers, componentIds } = registration;
21	  const report = await runContractKit({ manifest, policy, readers, componentIds });
22	  // The later SDK task owns the kit. Do not turn an unknown report into a pass.
23	  let passed;
24	  if (typeof report?.ok === 'boolean') passed = report.ok;
25	  else if (typeof report?.passed === 'boolean') passed = report.passed;
26	  else if (Number.isInteger(report?.failed) && Number.isInteger(report?.passed)) {
27	    passed = report.failed === 0 && report.passed > 0;
28	  } else throw new Error('Unknown contract report: expected ok/passed boolean or passed/failed counts');
29	  process.stdout.write(`${resultMarker}${JSON.stringify({ passed })}\n`);
30	  if (!passed) process.exitCode = 1;
31	}
32	
33	function run(command, args, cwd, options = {}) {
34	  return new Promise((done) => {
35	    const child = spawn(command, args, { cwd, env: process.env, ...options });
36	    let output = '';
37	    child.stdout?.on('data', (chunk) => { output += chunk; });
38	    child.stderr?.on('data', (chunk) => { output += chunk; });
39	    child.on('error', (error) => done({ code: 1, output: error.message }));
40	    child.on('close', (code) => done({ code: code ?? 1, output }));
41	  });
42	}
43	
44	async function smoke(baseUrl, add) {
45	  const origin = new URL(baseUrl).origin;
46	  const request = async (path, options) => fetch(`${origin}${path}`, {
47	    redirect: 'manual', signal: AbortSignal.timeout(10_000), ...options,
48	  });
49	  const checks = [
50	    ['resource metadata', async () => {
51	      const response = await request('/.well-known/oauth-protected-resource/api/mcp');
52	      if (response.status !== 200) throw new Error(`HTTP ${response.status}, expected 200`);
53	      const body = await response.json();
54	      if (body.resource !== `${origin}/api/mcp`) throw new Error('resource does not match app origin /api/mcp');
55	    }],
56	    ['unauthenticated MCP', async () => {
57	      const response = await request('/api/mcp', {
58	        method: 'POST', headers: { 'Content-Type': 'application/json', Accept: 'application/json, text/event-stream' },
59	        body: JSON.stringify({ jsonrpc: '2.0', id: 1, method: 'tools/list', params: {} }),
60	      });
61	      if (response.status !== 401) throw new Error(`HTTP ${response.status}, expected 401`);
62	      if (!response.headers.get('www-authenticate')?.includes('resource_metadata')) {
63	        throw new Error('WWW-Authenticate lacks resource_metadata');
64	      }
65	    }],
66	    ['project document', async () => {
67	      const response = await request('/.well-known/contour-project.json');
68	      if (response.status !== 200) throw new Error(`HTTP ${response.status}, expected 200`);
69	    }],
70	  ];
71	  for (const [name, check] of checks) {
72	    try { await check(); add(name, 'PASS', ''); }
73	    catch (error) { add(name, 'FAIL', error.message); }
74	  }
75	}
76	
77	async function main(args) {
78	  if (!args[0] || args[0].startsWith('--') ||
79	      !(args.length === 1 || (args.length === 3 && args[1] === '--base-url'))) {
80	    console.error('Usage: node verify.mjs <appDir> [--base-url [REDACTED:APP_URL]]');
81	    return 1;
82	  }
83	  const appDir = await realpath(resolve(args[0]));
84	  const rows = [];
85	  const add = (check, status, details) => rows.push({ check, status, details });
86	  const typecheck = await run('pnpm', ['exec', 'tsc', '--noEmit'], appDir);
87	  add('typecheck', typecheck.code === 0 ? 'PASS' : 'FAIL', typecheck.code === 0 ? '' : `tsc exited ${typecheck.code}; run pnpm exec tsc --noEmit in the app for diagnostics`);
88	
89	  let unavailable = false;
90	  const appRequire = createRequire(resolve(appDir, 'package.json'));
91	  let kitFile;
92	  try { kitFile = appRequire.resolve('@contour/sdk/testing'); }
93	  catch (error) {
94	    if (['MODULE_NOT_FOUND', 'ERR_PACKAGE_PATH_NOT_EXPORTED'].includes(error.code)) {
95	      unavailable = true;
96	      add('contract kit', 'UNAVAILABLE', 'contract kit unavailable');
97	    } else add('contract kit', 'FAIL', 'Cannot resolve @contour/sdk/testing');
98	  }
99	  if (kitFile) {
100	    try {
101	      const config = JSON.parse(await readFile(resolve(appDir, 'contour.config.json'), 'utf8'));
102	      if (typeof config.contourModule !== 'string' || isAbsolute(config.contourModule)) {
103	        throw new Error('contourModule must be an app-relative module path');
104	      }
105	      const moduleFile = await realpath(resolve(appDir, config.contourModule));
106	      const moduleRelative = relative(appDir, moduleFile);
107	      if (moduleRelative === '..' || moduleRelative.startsWith('../')) throw new Error('contourModule escapes appDir');
108	      const nodeArgs = ['--conditions=react-server'];
109	      // tsx handles TSX, workspace TS exports, and the app's tsconfig aliases.
110	      try { nodeArgs.push('--import', pathToFileURL(appRequire.resolve('tsx')).href); }
111	      catch {
112	        if (['.ts', '.tsx', '.mts', '.cts'].includes(extname(moduleFile)) || extname(kitFile) === '.ts') {
113	          throw new Error('Install tsx in the app to load its TypeScript contourModule and SDK');
