@import "tailwindcss";
@import "../components/desk/desk.css";

@theme inline { --font-sans: var(--font-geist); }
:root {
  color-scheme: light;
  --ink: oklch(0.255 0.028 258);
  --muted: oklch(0.475 0.025 258);
  --surface: oklch(1 0 0);
  --canvas: oklch(0.977 0.003 258);
  --line: oklch(0.905 0.01 258);
  --input-line: oklch(0.65 0.02 258);
  --brand: oklch(0.425 0.145 260);
  --brand-soft: oklch(0.962 0.019 260);
  --danger: oklch(0.445 0.16 26);
  --danger-soft: oklch(0.971 0.014 26);
  --warning: oklch(0.455 0.105 70);
  --warning-soft: oklch(0.968 0.027 80);
  --success: oklch(0.395 0.085 155);
  --success-soft: oklch(0.963 0.019 155);
  --radius: 12px;
  --chrome: oklch(0.245 0.055 260);
  --focus: oklch(0.53 0.18 260);
}
* { box-sizing: border-box; }
body { margin: 0; background: var(--canvas); color: var(--ink); font-family: var(--font-geist), system-ui, sans-serif; font-size: 14px; line-height: 1.5; -webkit-font-smoothing: antialiased; }
a { color: var(--brand); text-underline-offset: 3px; text-decoration-skip-ink: auto; }
button, input, textarea, select { font: inherit; }
button, summary { cursor: pointer; }
button, .button { transition: background-color 140ms cubic-bezier(0.2,0,0,1), color 140ms cubic-bezier(0.2,0,0,1); }
button:disabled { cursor: wait; opacity: .65; }
:focus-visible { outline: 3px solid var(--focus); outline-offset: 3px; }
.workspace-header :focus-visible, .login-story :focus-visible { outline-color: white; }
h1, h2, h3, p { margin: 0; }
h1 { font-size: clamp(1.8rem, 3vw, 2.15rem); line-height: 1.15; font-weight: 650; letter-spacing: -.045em; text-wrap: balance; }
h2 { font-size: 1.05rem; font-weight: 650; line-height: 1.35; letter-spacing: -.02em; }
h3 { font-size: .95rem; font-weight: 600; line-height: 1.4; }
p { text-wrap: pretty; }
::selection { background: var(--brand-soft); color: var(--ink); }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
.skip-link { position: fixed; inset-block-start: 8px; inset-inline-start: 16px; transform: translateY(-150%); background: white; padding: 12px 20px; z-index: 30; border-radius: 8px; }
.skip-link:focus { transform: translateY(0); }
.brand { display: inline-flex; align-items: center; gap: 11px; font-size: 18px; font-weight: 650; letter-spacing: -.035em; white-space: nowrap; }
