.data-table th { font-weight: 500; color: var(--muted); background: var(--canvas); text-align: start; padding: 12px 20px; }
.data-table td { padding: 17px 20px; border-block-start: 1px solid var(--line); vertical-align: top; }
.data-table td strong { display: block; font-weight: 550; }
.table-surface { border-radius: var(--radius); background: var(--surface); box-shadow: 0 0 0 1px var(--line); overflow: auto; }
.numeric { text-align: end !important; font-variant-numeric: tabular-nums; }
.customer-name { display: flex; gap: 12px; align-items: center; }
