  .login-layout { grid-template-columns: 1fr; }.login-story { padding: 28px 24px; gap: 30px; }.login-story h1 { font-size: 36px; }.login-story > div > p { margin-block-start: 12px; font-size: 14px; }.login-story-footer, .login-note { display: none; }.login-form-panel { padding: 34px 24px 50px; }
