1	import "server-only";
2	import { AGENT_SCOPES, ContourError, type Scope } from "../../core/types";
3	import type { ServerContext } from "../context";
4	
5	export type GrantRow = {
6	  id: string;
7	  subject_id: string;
8	  tenant_id: string;
9	  app_id: string;
10	  client_id: string;
11	  scopes: string[];
12	  surfaces: string[];
13	  grant_revision: number;
14	  revoked_at: string | null;
15	  created_at: string;
16	  updated_at: string;
17	};
18	
19	export type GrantSummary = {
20	  id: string;
21	  clientId: string;
22	  clientName: string;
23	  /** "dcr" = self-registered (name unverified), "cimd" = metadata document at a URL. */
24	  clientKind: string;
25	  scopes: Scope[];
26	  surfaces: string[];
27	  createdAt: string;
28	  updatedAt: string;
29	  revokedAt: string | null;
30	};
31	
32	const GRANT_COLUMNS =
33	  "id, subject_id, tenant_id, app_id, client_id, scopes, surfaces, grant_revision, revoked_at, created_at, updated_at";
34	
35	export function agentScopesOnly(scopes: readonly string[]): Scope[] {
36	  return AGENT_SCOPES.filter((s) => scopes.includes(s));
37	}
38	
39	export type Grants = ReturnType<typeof createGrants>;
40	
41	export function createGrants(ctx: ServerContext) {
42	  /** (Re-)consent. Bumps grant_revision so tokens from earlier consents stop working. */
43	  async function upsertGrant(p: {
44	    subjectId: string;
45	    tenantId: string;
46	    appId: string;
47	    clientId: string;
48	    scopes: Scope[];
49	    surfaces: string[];
50	  }): Promise<GrantRow> {
51	    const scopes = agentScopesOnly(p.scopes);
52	    if (scopes.length === 0) throw new ContourError("INVALID_INPUT", "No grantable scopes");
53	    const { data, error } = await ctx.db().rpc("contour_upsert_grant", {
54	      p_subject: p.subjectId,
55	      p_tenant: p.tenantId,
56	      p_app: p.appId,
57	      p_client: p.clientId,
58	      p_scopes: scopes,
59	      p_surfaces: p.surfaces,
60	    });
61	    const row = (Array.isArray(data) ? data[0] : data) as GrantRow | null;
62	    if (error || !row?.id) throw new ContourError("INTERNAL", "Could not record the grant");
63	    return row;
64	  }
65	
66	  /** Grant lookup by id; callers must still check ownership/state. */
67	  async function getGrantById(grantId: string): Promise<GrantRow | null> {
68	    const { data, error } = await ctx.db().from("oauth_grants").select(GRANT_COLUMNS).eq("id", grantId).maybeSingle();
69	    if (error) throw new ContourError("INTERNAL", "Grant lookup failed");
70	    return (data as GrantRow | null) ?? null;
71	  }
72	
73	  async function findGrant(subjectId: string, tenantId: string, appId: string, clientId: string): Promise<GrantRow | null> {
74	    const { data, error } = await ctx.db()
75	      .from("oauth_grants")
76	      .select(GRANT_COLUMNS)
77	      .eq("subject_id", subjectId)
78	      .eq("tenant_id", tenantId)
79	      .eq("app_id", appId)
80	      .eq("client_id", clientId)
81	      .maybeSingle();
82	    if (error) throw new ContourError("INTERNAL", "Grant lookup failed");
83	    return (data as GrantRow | null) ?? null;
84	  }
85	
86	  /** Revoke every live token of the given grants (access + refresh). */
87	  async function revokeTokensForGrants(grantIds: string[]): Promise<void> {
88	    if (grantIds.length === 0) return;
89	    const { error } = await ctx.db()
90	      .from("oauth_tokens")
91	      .update({ revoked_at: new Date().toISOString() })
92	      .in("grant_id", grantIds)
93	      .is("revoked_at", null);
94	    if (error) throw new ContourError("INTERNAL", "Token revocation failed");
95	  }
96	
97	  async function audit(tenantId: string, appId: string, subjectId: string | null, kind: string, ref: string, detail: Record<string, unknown>) {
98	    const { error } = await ctx.db()
99	      .from("audit_events")
100	      .insert({ tenant_id: tenantId, app_id: appId, subject_id: subjectId, surface_id: null, kind, ref, detail });
101	    if (error) console.error("[contour] audit insert failed", error.code ?? "unknown");
102	  }
103	
104	  /** Agent connections for the signed-in user's Connected agents page. */
105	  async function listGrantsForUser(subjectId: string, tenantId: string): Promise<GrantSummary[]> {
106	    const { data, error } = await ctx.db()
107	      .from("oauth_grants")
108	      .select(`${GRANT_COLUMNS}, oauth_clients(client_name, kind)`)
109	      .eq("subject_id", subjectId)
110	      .eq("tenant_id", tenantId)
111	      .eq("app_id", ctx.cfg.appId)
112	      .order("created_at", { ascending: false })
113	      .limit(50);
114	    if (error) throw new ContourError("INTERNAL", "Could not list connected agents");
115	    type Row = GrantRow & { oauth_clients: { client_name: string; kind: string } | { client_name: string; kind: string }[] | null };
116	    return ((data ?? []) as unknown as Row[]).map((r) => {
117	      const c = Array.isArray(r.oauth_clients) ? r.oauth_clients[0] : r.oauth_clients;
118	      return {
119	        id: r.id,
120	        clientId: r.client_id,
121	        clientName: c?.client_name ?? "Unknown client",
122	        clientKind: c?.kind ?? "unknown",
123	        scopes: agentScopesOnly(r.scopes),
124	        surfaces: r.surfaces,
125	        createdAt: r.created_at,
126	        updatedAt: r.updated_at,
127	        revokedAt: r.revoked_at,
128	      };
129	    });
130	  }
131	
132	  /** User revokes one of their own agent grants. Returns false if not found / not theirs. */
133	  async function revokeGrant(subjectId: string, tenantId: string, grantId: string): Promise<boolean> {
134	    if (!/^[0-9a-f-]{36}$/i.test(grantId)) return false;
135	    const now = new Date().toISOString();
136	    const { data, error } = await ctx.db()
137	      .from("oauth_grants")
138	      .update({ revoked_at: now, updated_at: now })
139	      .eq("id", grantId)
140	      .eq("subject_id", subjectId)
141	      .eq("tenant_id", tenantId)
142	      .eq("app_id", ctx.cfg.appId)
143	      .select("id, revoked_at");
144	    if (error) throw new ContourError("INTERNAL", "Could not revoke the grant");
145	    if (!data || data.length === 0) return false;
146	    await revokeTokensForGrants([grantId]);
147	    await audit(tenantId, ctx.cfg.appId, subjectId, "agent_grant_revoked", grantId, { by: "user" });
148	    return true;
149	  }
150	
151	  /** Operator kill switch: revoke every agent grant for a tenant + app. Returns the count. */
152	  async function revokeAllGrantsForApp(tenantId: string, appId: string, operatorSubjectId?: string): Promise<number> {
153	    const now = new Date().toISOString();
154	    const { data, error } = await ctx.db()
155	      .from("oauth_grants")
156	      .update({ revoked_at: now, updated_at: now })
157	      .eq("tenant_id", tenantId)
158	      .eq("app_id", appId)
159	      .is("revoked_at", null)
160	      .select("id");
161	    if (error) throw new ContourError("INTERNAL", "Could not revoke grants");
162	    const ids = (data ?? []).map((r) => r.id as string);
163	    // Also sweep tokens of grants revoked earlier (idempotent).
164	    const { data: all } = await ctx.db().from("oauth_grants").select("id").eq("tenant_id", tenantId).eq("app_id", appId);
165	    await revokeTokensForGrants((all ?? []).map((r) => r.id as string));
166	    await audit(tenantId, appId, operatorSubjectId ?? null, "agent_grants_revoked_all", appId, { count: ids.length, by: "operator" });
167	    return ids.length;
168	  }
169	
170	  /** Revoke a grant because of a security event (refresh-token reuse, code replay). */
171	  async function revokeGrantForSecurityEvent(grant: GrantRow, reason: string): Promise<void> {
172	    const now = new Date().toISOString();
173	    await ctx.db()
174	      .from("oauth_grants")
175	      .update({ revoked_at: now, updated_at: now })
176	      .eq("id", grant.id)
177	      .eq("subject_id", grant.subject_id)
178	      .eq("tenant_id", grant.tenant_id);
179	    await revokeTokensForGrants([grant.id]);
180	    await audit(grant.tenant_id, grant.app_id, grant.subject_id, "agent_grant_revoked", grant.id, { by: "system", reason });
181	  }
182	
183	  return {
184	    upsertGrant,
185	    getGrantById,
186	    findGrant,
187	    revokeTokensForGrants,
188	    listGrantsForUser,
189	    revokeGrant,
190	    revokeAllGrantsForApp,
191	    revokeGrantForSecurityEvent,
192	  };
193	}
194

