@theme inline { --font-sans: var(--font-geist); }
:root {
  color-scheme: light;
  --ink: oklch(0.255 0.028 258);
  --muted: oklch(0.475 0.025 258);
  --surface: oklch(1 0 0);
  --canvas: oklch(0.977 0.003 258);
  --line: oklch(0.905 0.01 258);
  --input-line: oklch(0.65 0.02 258);
  --brand: oklch(0.425 0.145 260);
  --brand-soft: oklch(0.962 0.019 260);
  --danger: oklch(0.445 0.16 26);
  --danger-soft: oklch(0.971 0.014 26);
  --warning: oklch(0.455 0.105 70);
  --warning-soft: oklch(0.968 0.027 80);
  --success: oklch(0.395 0.085 155);
  --success-soft: oklch(0.963 0.019 155);
  --radius: 12px;
  --chrome: oklch(0.245 0.055 260);
  --focus: oklch(0.53 0.18 260);
}
* { box-sizing: border-box; }
body { margin: 0; background: var(--canvas); color: var(--ink); font-family: var(--font-geist), system-ui, sans-serif; font-size: 14px; line-height: 1.5; -webkit-font-smoothing: antialiased; }
a { color: var(--brand); text-underline-offset: 3px; text-decoration-skip-ink: auto; }
button, input, textarea, select { font: inherit; }
button, summary { cursor: pointer; }
button, .button { transition: background-color 140ms cubic-bezier(0.2,0,0,1), color 140ms cubic-bezier(0.2,0,0,1); }
button:disabled { cursor: wait; opacity: .65; }
:focus-visible { outline: 3px solid var(--focus); outline-offset: 3px; }
.workspace-header :focus-visible, .login-story :focus-visible { outline-color: white; }
h1, h2, h3, p { margin: 0; }
h1 { font-size: clamp(1.8rem, 3vw, 2.15rem); line-height: 1.15; font-weight: 650; letter-spacing: -.045em; text-wrap: balance; }
h2 { font-size: 1.05rem; font-weight: 650; line-height: 1.35; letter-spacing: -.02em; }
h3 { font-size: .95rem; font-weight: 600; line-height: 1.4; }
p { text-wrap: pretty; }
::selection { background: var(--brand-soft); color: var(--ink); }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
.skip-link { position: fixed; inset-block-start: 8px; inset-inline-start: 16px; transform: translateY(-150%); background: white; padding: 12px 20px; z-index: 30; border-radius: 8px; }
.skip-link:focus { transform: translateY(0); }
.brand { display: inline-flex; align-items: center; gap: 11px; font-size: 18px; font-weight: 650; letter-spacing: -.035em; white-space: nowrap; }
.brand-mark { position: relative; display: inline-flex; align-items: center; justify-content: center; width: 32px; height: 32px; font-size: 23px; line-height: 1; border-radius: 8px; color: var(--chrome); background: white; font-weight: 700; }
.brand-mark > span { position: absolute; inset-block-start: -5px; inset-inline-end: -4px; font-size: 15px; background: var(--chrome); color: white; border-radius: 3px; padding: 1px; }
.brand-product { display: block; font-size: 11px; line-height: 1.15; letter-spacing: .01em; font-weight: 450; color: oklch(.83 .017 260); }
.brand-link { color: white; text-decoration: none; }
.workspace-header { position: sticky; inset-block-start: 0; z-index: 20; background: var(--chrome); color: white; }
.header-inner { display: flex; align-items: center; gap: 36px; min-height: 72px; max-width: 1440px; margin-inline: auto; padding-inline: 32px; }
.workspace-header nav { display: flex; align-self: stretch; gap: 4px; align-items: center; }
.workspace-header nav a { display: flex; align-items: center; min-height: 40px; padding: 8px 15px; color: oklch(.84 .02 260); font-weight: 500; text-decoration: none; border-radius: 7px; }
.workspace-header nav a:hover { color: white; background: oklch(1 0 0 / .07); }
.workspace-header nav a[aria-current="page"] { color: white; background: oklch(1 0 0 / .12); box-shadow: inset 0 0 0 1px oklch(1 0 0 / .05); }
.account-menu { margin-inline-start: auto; position: relative; }
.account-menu summary { list-style: none; display: flex; align-items: center; gap: 9px; min-height: 44px; padding-inline: 6px; border-radius: 6px; }
.account-menu summary::-webkit-details-marker { display: none; }
.avatar { display: inline-flex; flex-shrink: 0; align-items: center; justify-content: center; width: 32px; height: 32px; background: oklch(.93 .01 260); color: var(--ink); border-radius: 50%; font-size: 11px; font-weight: 650; }
.account-chevron { opacity: .8; }
.account-popover { position: absolute; inset-inline-end: 0; inset-block-start: calc(100% + 10px); min-width: 260px; padding: 18px; border-radius: var(--radius); background: var(--surface); color: var(--ink); box-shadow: 0 12px 36px oklch(.245 .055 260 / .13), 0 0 0 1px var(--line); display: grid; gap: 7px; }
.account-popover > span, .account-popover p { color: var(--muted); font-size: 12px; }
.account-popover a, .account-popover button { display: block; width: 100%; margin-block-start: 4px; padding: 10px 12px; border-radius: 6px; background: var(--canvas); color: var(--ink); font-size: 13px; text-align: start; text-decoration: none; border: 0; }
.account-popover :focus-visible { outline-color: var(--focus); }
.workspace-main { max-width: 1440px; margin-inline: auto; padding: 34px 32px 48px; min-height: calc(100dvh - 130px); }
.page-heading { display: flex; align-items: center; justify-content: space-between; gap: 24px; margin-block-end: 26px; }
.page-heading p { color: var(--muted); margin-block-start: 7px; }
.page-context { display: flex; align-items: center; gap: 10px; color: var(--muted); font-size: 12px; }
.scope-badge, .neutral-badge { padding: 6px 10px; background: var(--surface); color: var(--muted); border: 1px solid var(--line); border-radius: 6px; white-space: nowrap; font-size: 12px; }
.desk-layout { display: grid; grid-template-columns: minmax(0, 1fr) 340px; gap: 24px; align-items: start; margin-block-start: 24px; }
.desk-primary, .desk-secondary { display: grid; gap: 24px; min-width: 0; }
.desk-bottom { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; align-items: start; }
.desk-toolbar { display: flex; justify-content: space-between; align-items: center; gap: 16px; margin: 0 0 12px; flex-wrap: wrap; }
.filter-tabs { display: inline-flex; gap: 2px; padding: 3px; border: 1px solid var(--line); border-radius: 8px; background: var(--surface); }
.filter-tabs a { display: block; padding: 7px 13px; border-radius: 5px; color: var(--muted); text-decoration: none; min-height: 34px; font-size: 13px; font-weight: 500; }
.filter-tabs a[aria-current="page"] { background: var(--brand-soft); color: var(--brand); }
.view-options { display: flex; align-items: center; gap: 10px; }
.view-options details { position: relative; }
.view-options summary { padding: 8px 12px; border-radius: 6px; border: 1px solid var(--line); background: var(--surface); font-size: 12px; }
.view-option-menu { position: absolute; inset-inline-end: 0; inset-block-start: calc(100% + 6px); padding: 16px; width: 240px; background: var(--surface); box-shadow: 0 10px 30px oklch(.245 .055 260 / .1), 0 0 0 1px var(--line); border-radius: 9px; z-index: 10; }
.view-option-menu form { display: grid; gap: 12px; }
.view-option-menu label { display: grid; gap: 5px; }
.view-option-menu select { padding: 7px; }
.search-form { display: flex; gap: 8px; }
.search-form input { min-width: 0; width: 220px; padding: 8px 12px; background: var(--surface); border: 1px solid var(--line); border-radius: 6px; }
.button { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 40px; padding: 9px 16px; border-radius: 7px; font-weight: 550; font-size: 13px; text-decoration: none; border: 1px solid var(--line); background: var(--surface); color: var(--ink); white-space: nowrap; }
.button:hover { background: var(--canvas); }
.button-primary { background: var(--brand); color: white; border-color: transparent; box-shadow: inset 0 1px 0 oklch(1 0 0 / .1); }
.button-primary:hover { background: oklch(.365 .13 260); }
.button-small { min-height: 34px; padding: 6px 12px; }
.notice { padding: 13px 16px; border-radius: 8px; margin-block-end: 18px; line-height: 1.5; }
.notice-error { background: var(--danger-soft); color: var(--danger); border: 1px solid oklch(.85 .07 26); }
.notice-success { background: var(--success-soft); color: var(--success); border: 1px solid oklch(.84 .06 155); }
.field { display: grid; gap: 7px; }
.field label, legend { font-weight: 550; }
.field input, .field textarea, .field select { border: 1px solid var(--input-line); border-radius: 7px; padding: 11px 12px; min-width: 0; width: 100%; background: var(--surface); color: var(--ink); min-height: 44px; }
input::placeholder, textarea::placeholder { color: var(--muted); opacity: 1; }
.field-hint, .muted { color: var(--muted); font-size: 13px; }
.stack-form { display: grid; gap: 22px; }
.settings-layout { display: grid; grid-template-columns: minmax(0, 760px) 1fr; gap: 64px; }
.settings-section { padding: 25px 28px; background: var(--surface); border-radius: var(--radius); box-shadow: 0 0 0 1px var(--line), 0 2px 4px oklch(.245 .055 260 / .015); }
.settings-section h2 { margin-block-end: 20px; }
.profile-fields { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
.preference-list { border: 0; margin: 0; padding: 0; display: grid; gap: 20px; }
.preference-list legend { margin-block-end: 22px; font-size: 1.05rem; }
.preference { display: flex; align-items: start; gap: 14px; cursor: pointer; }
.preference input { width: 18px; height: 18px; margin-block-start: 3px; accent-color: var(--brand); flex-shrink: 0; }
.preference strong { display: block; font-weight: 550; }
.preference span span { display: block; color: var(--muted); font-size: 13px; margin-block-start: 3px; }
.settings-aside { padding-block-start: 25px; }
.settings-aside h2 { margin-block-end: 8px; }
.settings-aside p { color: var(--muted); max-width: 34ch; }
.integration-placeholder { margin-block-start: 40px; padding-block-start: 28px; border-block-start: 1px dashed var(--line); }
.integration-placeholder .neutral-badge { display: inline-block; margin-block-start: 14px; }
.data-table { width: 100%; border-collapse: collapse; font-size: 13px; }
.data-table th { font-weight: 500; color: var(--muted); background: var(--canvas); text-align: start; padding: 12px 20px; }
.data-table td { padding: 17px 20px; border-block-start: 1px solid var(--line); vertical-align: top; }
.data-table td strong { display: block; font-weight: 550; }
.table-surface { border-radius: var(--radius); background: var(--surface); box-shadow: 0 0 0 1px var(--line); overflow: auto; }
.numeric { text-align: end !important; font-variant-numeric: tabular-nums; }
.customer-name { display: flex; gap: 12px; align-items: center; }
.customer-name .avatar { width: 36px; height: 36px; }
.team-list { display: grid; gap: 24px; max-width: 1000px; }
.team-title { display: flex; align-items: center; justify-content: space-between; gap: 24px; margin-block-end: 18px; }
.team-title p { color: var(--muted); margin-block-start: 4px; }
.team-member { display: flex; align-items: center; gap: 12px; padding-block: 12px; }
.team-member + .team-member { border-block-start: 1px solid var(--line); }
.team-member strong { display: block; }
.team-member > .neutral-badge { margin-inline-start: auto; }
.empty-page { min-height: 420px; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; padding: 40px 24px; gap: 16px; }
.empty-page p { color: var(--muted); max-width: 50ch; }
.empty-illustration { display: flex; align-items: end; gap: 10px; min-height: 90px; margin-block-end: 12px; }
.empty-illustration span { width: 20px; border-radius: 4px 4px 0 0; background: oklch(.89 .015 258); height: 40px; }
.empty-illustration span:nth-child(2) { height: 60px; }.empty-illustration span:nth-child(3) { height: 52px; }.empty-illustration span:nth-child(4) { height: 78px; }.empty-illustration span:nth-child(5) { height: 65px; }
.workspace-footer { max-width: 1440px; margin-inline: auto; padding: 18px 32px; color: var(--muted); font-size: 12px; display: flex; justify-content: space-between; border-block-start: 1px solid var(--line); }
.login-layout { min-height: 100dvh; display: grid; grid-template-columns: 46% 54%; }
.login-story { background: var(--chrome); color: white; padding: 52px 64px 30px; display: flex; flex-direction: column; justify-content: space-between; gap: 80px; }
.login-story h1 { font-size: clamp(2.7rem, 4.5vw, 4.5rem); line-height: 1.08; letter-spacing: -.055em; font-weight: 550; }
.login-story > div > p { color: oklch(.85 .02 260); max-width: 35ch; font-size: 16px; line-height: 1.7; margin-block-start: 26px; }
.login-note { margin-block-start: 70px; display: flex; gap: 18px; font-size: 14px; color: white; }
.login-note-line { width: 3px; border-radius: 3px; background: oklch(.65 .11 260); }
.login-note span:not(.login-note-line) { color: oklch(.8 .015 260); font-size: 13px; }
.login-story-footer { color: oklch(.8 .015 260); font-size: 12px; }
.login-form-panel { display: flex; justify-content: center; align-items: center; padding: 48px 32px; background: var(--surface); }
.login-form-inner { width: 100%; max-width: 370px; }
.login-form-inner h2 { font-size: 29px; letter-spacing: -.04em; }
.login-form-inner > p { color: var(--muted); margin-block-start: 8px; margin-block-end: 32px; }
.login-form-inner .button { min-height: 46px; }
.demo-logins { margin-block-start: 32px; font-size: 12px; color: var(--muted); border-block-start: 1px solid var(--line); padding-block-start: 24px; }
.demo-logins summary { font-size: 13px; color: var(--ink); padding-block: 8px; }
.demo-logins p { margin-block-start: 12px; }
.demo-logins ul { list-style: none; padding: 0; margin-block: 14px; display: grid; gap: 12px; }
.demo-logins li strong { display: block; color: var(--ink); }
.skeleton { border-radius: 9px; background: oklch(.925 .006 258); }
.skeleton-heading { width: 230px; height: 42px; margin-block-end: 28px; }
.skeleton-alert { height: 100px; margin-block-end: 24px; }
.loading-grid { display: grid; grid-template-columns: 2fr 1fr; gap: 24px; }
.skeleton-queue { height: 450px; }
@media (prefers-reduced-motion: no-preference) { button:active, .button:active { transform: scale(.96); } .skeleton { animation: pulse 1.6s cubic-bezier(.2,0,0,1) infinite; } }
@keyframes pulse { 50% { opacity: .5; } }
@media (forced-colors: active) { :focus-visible { outline-color: Highlight; } .button, .neutral-badge, .scope-badge { border: 1px solid ButtonText; } }
@media (max-width: 70rem) { .header-inner { gap: 20px; } .desk-layout { grid-template-columns: minmax(0, 1fr) 300px; gap: 18px; }.desk-bottom { grid-template-columns: 1fr; }.login-story { padding: 40px; } }
@media (max-width: 60rem) { .desk-layout { grid-template-columns: 1fr; }.desk-secondary { grid-template-columns: 1fr 1fr; }.desk-bottom { grid-template-columns: 1fr 1fr; }.header-inner { padding-inline: 24px; gap: 18px; }.workspace-header nav a { padding-inline: 10px; }.settings-layout { gap: 32px; grid-template-columns: minmax(0, 1fr) 240px; } }
@media (max-width: 48rem) {
  .header-inner { display: grid; grid-template-columns: 1fr auto; padding: 12px 16px 0; gap: 8px 16px; }
  .workspace-header nav { grid-column: 1 / -1; grid-row: 2; gap: 0; justify-content: space-between; padding-block-end: 9px; }
  .workspace-header nav a { padding: 7px 10px; min-height: 36px; font-size: 13px; }
  .account-menu { grid-column: 2; grid-row: 1; }.account-name { display: none; }
  .workspace-main { padding: 26px 16px 36px; }.workspace-footer { padding: 18px 16px; }
  .page-heading { align-items: start; gap: 16px; }.page-context { flex-direction: column; align-items: end; }.page-context > time { display: none; }
  .desk-bottom, .desk-secondary, .settings-layout, .profile-fields, .loading-grid { grid-template-columns: 1fr; }
  .settings-aside { padding: 0 8px; }.settings-section { padding: 22px; }
  input, textarea, select { font-size: 16px; }.search-form input { width: min(200px, 50vw); }
  .login-layout { grid-template-columns: 1fr; }.login-story { padding: 28px 24px; gap: 30px; }.login-story h1 { font-size: 36px; }.login-story > div > p { margin-block-start: 12px; font-size: 14px; }.login-story-footer, .login-note { display: none; }.login-form-panel { padding: 34px 24px 50px; }
  .data-table td, .data-table th { padding: 14px; }.customer-company { display: none; }
}
@media (max-width: 25rem) { .workspace-header nav a { padding-inline: 7px; }.brand { font-size: 16px; }.page-heading { flex-direction: column; }.page-context { align-items: start; }.view-options { width: 100%; justify-content: space-between; }.filter-tabs a { padding-inline: 10px; } }
.range-selector { display: flex; justify-content: end; gap: 4px; margin-block-end: 12px; }
.range-selector a { min-height: 36px; display: inline-flex; align-items: center; padding: 7px 12px; text-decoration: none; color: var(--muted); border-radius: 6px; font-size: 12px; }
.range-selector a[aria-current="page"] { background: var(--surface); color: var(--brand); box-shadow: 0 0 0 1px var(--line); }
.panel-variant-link { display: inline-block; padding-block: 10px; font-size: 12px; }
.back-link { display: inline-block; margin-block-end: 20px; font-size: 13px; }
.ticket-detail-layout { display: grid; grid-template-columns: minmax(0, 1fr) 300px; gap: 24px; align-items: start; }
.thread-message { padding-block: 20px; }.thread-message + .thread-message { border-block-start: 1px solid var(--line); }
.thread-message-heading { display: flex; justify-content: space-between; flex-wrap: wrap; gap: 8px; margin-block-end: 12px; }
.thread-message-heading time { color: var(--muted); font-size: 12px; font-variant-numeric: tabular-nums; }
.thread-message p { white-space: pre-wrap; overflow-wrap: anywhere; line-height: 1.65; max-width: 70ch; }
.ticket-facts dl { margin-block: 0 24px; }.ticket-facts dl > div { display: flex; justify-content: space-between; gap: 18px; padding-block: 10px; }
.ticket-facts dt { color: var(--muted); }.ticket-facts dd { margin: 0; text-align: end; text-transform: capitalize; }
@media (max-width: 48rem) { .ticket-detail-layout { grid-template-columns: 1fr; } }

input.content:
/* Contour integration styles, built only from Northwind's existing tokens. */

/* Adaptive desk region: same 24px rhythm as the original desk layout. */
.cs-grid { display: grid; gap: 24px; align-items: start; }
.cs-region { display: grid; gap: 24px; align-content: start; min-width: 0; }
.cs-slot { min-width: 0; }
.cs-root[data-density="compact"] .cs-grid, .cs-root[data-density="compact"] .cs-region { gap: 18px; }
.cs-slot[data-changed="true"] { outline: 2px solid var(--brand); outline-offset: 4px; border-radius: var(--radius); }

/* A panel that failed to render (SDK ComponentBoundary). */
.hc-failed { padding: 22px; background: var(--surface); border-radius: var(--radius); box-shadow: 0 0 0 1px var(--line); display: grid; gap: 8px; justify-items: start; }
.hc-failed[data-required="true"] { background: var(--warning-soft); box-shadow: inset 3px 0 0 var(--warning), 0 0 0 1px var(--line); }
.hc-title { font-size: .95rem; font-weight: 600; }
.hc-failed .btn { min-height: 34px; padding: 6px 12px; border-radius: 7px; border: 1px solid var(--line); background: var(--surface); color: var(--ink); font-size: 13px; font-weight: 550; }

/* Proposal preview (SDK ViewPreview). */
.contour-preview { display: grid; gap: 24px; padding-block-end: 96px; }
.contour-preview .panel { background: var(--surface); border-radius: var(--radius); box-shadow: 0 0 0 1px var(--line); }
.contour-preview .section-title { font-size: 1.05rem; font-weight: 650; }
.contour-preview .meta { color: var(--muted); font-size: 12px; }
.contour-preview .seg { display: inline-flex; gap: 2px; padding: 3px; border: 1px solid var(--line); border-radius: 8px; background: var(--surface); }
.contour-preview .seg button, .contour-preview .seg label { display: inline-flex; align-items: center; gap: 6px; padding: 6px 12px; border: 0; border-radius: 5px; background: transparent; color: var(--muted); font-size: 13px; font-weight: 500; }
.contour-preview .seg button[aria-selected="true"], .contour-preview .seg label:has(input:checked) { background: var(--brand-soft); color: var(--brand); }
.contour-preview .seg input { accent-color: var(--brand); }
.vp-frame { overflow: hidden; padding: 16px; border-radius: var(--radius); background: var(--canvas); box-shadow: 0 0 0 1px var(--line); }
.vp-canvas { pointer-events: none; }
.contour-preview-facts { display: grid; grid-template-columns: auto 1fr; gap: 6px 18px; margin: 14px 0 0; }
.contour-preview-facts dt { color: var(--muted); }
.contour-preview-facts dd { margin: 0; font-weight: 550; }
.contour-preview-actions { position: sticky; inset-block-end: 0; z-index: 15; display: flex; flex-wrap: wrap; align-items: center; gap: 10px; padding: 14px 0; background: var(--canvas); border-block-start: 1px solid var(--line); }
.contour-preview-actions .notice { width: 100%; margin: 0; }
@media (min-width: 64rem) { .vp-tabs { display: none; } }
@media (max-width: 63.99rem) { .vp-pane:not([data-active="true"]) { display: none; } }

/* Connect an agent (SDK ConnectAgentPanel) and connected agents, in the settings aside. */
.contour-connect { display: grid; gap: 12px; }
.contour-connect-heading { margin: 0; }
.contour-connect-intro, .contour-connect-cloud { color: var(--muted); max-width: 34ch; }
.contour-connect-command { display: grid; gap: 8px; }
.contour-connect-code { margin: 0; padding: 12px; overflow-x: auto; background: var(--surface); border: 1px solid var(--line); border-radius: 7px; font-size: 12px; white-space: pre-wrap; overflow-wrap: anywhere; }
.contour-connect-copy { justify-self: start; min-height: 34px; padding: 6px 12px; border-radius: 7px; border: 1px solid var(--line); background: var(--surface); color: var(--ink); font-size: 13px; font-weight: 550; }
.contour-agents { display: grid; gap: 12px; margin-block-start: 20px; padding: 0; list-style: none; }
.contour-agents li { display: flex; justify-content: space-between; align-items: center; gap: 12px; }
.contour-agents strong { display: block; font-weight: 550; overflow-wrap: anywhere; }

/* Admin agent access controls. */
.contour-admin-actions { display: flex; flex-wrap: wrap; gap: 12px; align-items: center; margin-block-start: 18px; }

