vi.mock("../src/lib/db", () => ({
  getDb: () => ({ from: () => {
    let rows = [...fx.users];
    const chain = {
      select: () => chain,
      eq: (key: string, value: unknown) => { rows = rows.filter((row) => (row as Record<string, unknown>)[key] === value); return chain; },
      maybeSingle: async () => ({ data: rows[0] ?? null, error: null }),
    };
    return chain;
