import { beforeEach, describe, expect, it, vi } from "vitest";
import { AGENT_SCOPES, ALL_SCOPES, ContourError, createAdaptiveBroker, defineAdaptiveApp, hashJson, type ContourStore, type JsonValue, type Proposal, type StoredView, type VerifiedContext } from "@contour/sdk/core";
